const top_akshan = {
  champion: '아크샨',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'으로 계속 견제하며 가렌의 (P)\'인내심\' 회복이 시작되지 않게 하세요. 가렌이 (Q)\'결정타\'를 쓰고 빠르게 달려와 침묵을 걸려고 하면 뒤로 물러나며 거리 조절을 하는 것이 중요해요. 평타를 섞어 줘서 패시브 보호막을 챙기며 체력 이득을 보세요.', lv3: '가렌이 (W)\'용기\'를 켜면 받는 피해가 줄고 보호막이 생기니 그동안은 무리하게 교환하지 말고, 꺼진 뒤에 (E)\'영웅의 비상\'으로 진입했다가 빠져나오세요. (E)\'심판\' 회전이 시작되면 범위 밖으로 벗어나 방어력 감소 효과를 피하는 것이 좋아요. (Q)\'결정타\'로 침묵에 걸리면 스킬을 쓸 수 없으니 가렌이 평타를 때리러 붙기 전에 필요한 스킬을 먼저 쓰세요.', lv6: '가렌의 체력이 낮아졌을 때 (R)\'인과응보\'를 저장했다가 발사해 처치 각을 보세요. 다만 가렌의 (R)\'데마시아의 정의\'는 잃은 체력에 비례해 고정 피해를 입히니 내 체력이 낮을 때 곁에 오래 머물지 마세요. (E)\'영웅의 비상\'으로 지형을 활용해 빠르게 도망치거나 정글러가 올 때까지 라인을 당겨 받으세요.', item: '크라켄 학살자를 첫 코어로 선택해 세 번째 공격마다 추가 피해를 입히며 빠르게 체력을 깎으세요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 억제하면 마무리하기 편해요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 골드를 챙기며 견제하니 거리를 조절하며 (Q)\'복수의 부메랑\'을 맞춰 대응하세요. 갱플랭크의 근접 공격에는 (P)\'불의 심판\'으로 불이 붙으니 붙어서 오래 싸우지 말고 평타 사거리를 지키며 짧게 교환하는 것이 좋아요.', lv3: '(E)\'화약통\' 근처에서 싸우면 폭발 시 둔화와 피해를 입으니 통이 깔린 위치를 확인하고 피하세요. 갱플랭크가 (W)\'괴혈병 치료\'로 체력을 회복하기 전에 (E)\'영웅의 비상\'을 사용하여 빠르게 진입하거나 거리를 벌리세요. (Q)\'복수의 부메랑\'을 맞히면 이동 속도가 올라가니 이를 활용해 통의 폭발 범위를 벗어나세요.', lv6: '갱플랭크의 체력이 낮을 때 (R)\'인과응보\'를 사용하면 잃은 체력에 비례한 피해로 마무리하기 좋아요. (R)\'포탄 세례\' 범위 안에 있으면 이동 속도가 느려지니 장판을 피해 움직이며 (E)\'영웅의 비상\'으로 위치를 잡으세요. 갱플랭크가 (W)\'괴혈병 치료\'를 사용하지 못하는 타이밍을 노려 (R)\'인과응보\'로 킬각을 잡으세요.', item: '갱플랭크의 기본 공격 피해를 줄이기 위해 판금 장화를 선택하세요. 첫 코어 아이템은 공격 속도와 생명력 흡수를 제공하는 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복 효과를 줄이면서 (R)\'인과응보\'로 확실하게 마무리하세요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복하며 버티기 좋아요. (Q)\'복수의 부메랑\'을 사용해 멀리서 거리를 유지하며 미니언을 챙기되, 술통이 터지는 위치를 미리 예측해서 피해야 해요. 초반에는 무리하게 맞서기보다 (Q)\'복수의 부메랑\'의 사거리를 활용해 체력을 깎아두는 것이 좋아요.', lv3: '그라가스의 (E)\'몸통 박치기\'는 에어본을 유발하니 이 스킬을 먼저 빼도록 유도해야 해요. 그라가스가 (W)\'취중 분노\'를 사용해 받는 피해가 줄어든 동안에는 무리하게 싸우지 말고 (Q)\'복수의 부메랑\'으로 견제만 하세요. (E)\'몸통 박치기\'가 빠진 타이밍에 (E)\'영웅의 비상\'으로 진입해 (P)\'비열한 싸움\'의 추가 피해를 입히며 딜교환을 시작하세요.', lv6: '그라가스의 체력이 낮을 때 (R)\'인과응보\'를 사용하면 잃은 체력에 비례한 피해로 킬을 노릴 수 있어요. 다만 (R)\'술통 폭발\'에 밀려나면 위치가 흐트러지니 그라가스의 궁극기 위치를 항상 조심하세요. (E)\'영웅의 비상\'으로 지형을 타고 접근하거나 빠지고, 정글러가 근처에 있다면 함께 압박하세요.', item: '첫 코어 아이템으로 몰락한 왕의 검을 선택해 지속적인 전투 능력을 강화하세요. 신발은 그라가스의 마법 피해를 줄여 주고 (Q)\'술통 굴리기\' 둔화 시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 그라가스가 (P)\'서비스 시간\'으로 체력을 회복하는 것을 점화로 억제하여 확실하게 처치할 수 있어요.' },
    '그웬': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 던져 거리 조절을 하며 계속 견제하세요. 그웬이 (Q)\'싹둑싹둑!\'의 고정 피해를 입히려 다가오면 평타 세 번으로 보호막을 챙기며 짧게 딜교환하고 빠지세요. 그웬의 평타를 오래 맞으면 (P)\'가위 난도질\' 회복 때문에 손해를 봐요.', lv3: '(W)\'신성한 안개\'는 대상 지정 공격만 막으므로 (Q)\'복수의 부메랑\' 같은 투사체 스킬은 안개 속에서도 그대로 맞아요. (E)\'돌격가위\'로 거리를 좁히려 할 때 (E)\'영웅의 비상\'으로 지형에 고정해 빠르게 위치를 옮기며 대응하세요. 안개가 사라지는 타이밍에 맞춰 평타 콤보를 넣어 (P)\'비열한 싸움\' 보호막을 계속 갱신하세요.', lv6: '(R)\'바느질\' 바늘의 둔화에 걸리면 위험하니 (E)\'영웅의 비상\'으로 빠르게 이동해 바늘을 피하세요. 그웬의 체력이 낮아졌을 때 (R)\'인과응보\'를 발사해 잃은 체력 비례 피해로 마무리하세요. (W)\'신성한 안개\'가 켜진 동안에는 무리하게 노리지 말고 안개가 사라진 뒤에 킬각을 보세요.', item: '마법 저항력과 공격 속도를 챙겨 그웬의 마법 피해를 줄여 주는 마법사의 최후를 추천해요. 신발은 마법 저항력을 높이고 (R)\'바느질\'의 둔화 지속시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'로 체력을 계속 회복하는 그웬의 유지력을 꺾으려면 점화의 치유 감소 효과가 필요해요.' },
    '나르': { lv1: '나르의 (Q)\'부메랑 던지기\'는 사거리가 길어 견제가 매서우니 투사체 경로에서 벗어나 맞히는 횟수를 줄이세요. (Q)\'복수의 부메랑\'으로 함께 견제하며 (P)\'비열한 싸움\'의 보호막을 챙겨 피해를 상쇄하세요. 첫 웨이브에서는 둔화에 걸리지 않도록 거리 조절을 하며 짧게 교환해요.', lv3: '나르가 (E)\'폴짝\'으로 진입하면 (E)\'영웅의 비상\'을 사용해 지형을 타고 빠르게 이동하며 거리를 벌리세요. (P)\'분노 유전자\'로 메가 나르가 되면 (W)\'쿵쾅\' 기절 범위에 들어가지 않도록 정면을 피해야 해요. 작은 나르일 때 (Q)\'복수의 부메랑\'으로 계속해서 체력을 깎아 두는 것이 중요해요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절시키니 벽을 등지지 말고 넓은 곳에서 싸우세요. 체력이 낮아진 나르에게 (R)\'인과응보\'를 발사해 마무리하며 킬각을 잡으세요. 라인을 밀 때는 나르의 변신 타이밍을 확인하고 정글러 개입에 대비해 거리 조절을 하세요.', item: '크라켄 학살자로 기본 공격 피해량을 높여 지속적으로 압박하세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 체력이 낮은 나르를 확실하게 마무리하여 킬을 따내기에 좋아요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'을 사용하여 미니언을 먹으며 성장하려 해요. (Q)\'복수의 부메랑\'을 사용하여 나서스가 미니언 막타를 편하게 챙기지 못하도록 견제하세요. 나서스가 다가오면 거리를 유지하며 최대한 멀리서 공격하는 것이 중요해요.', lv3: '나서스의 (W)\'쇠약\'이 걸리면 이동 속도와 공격 속도가 줄어들어 도망치기 힘들어져요. 나서스가 (W)\'쇠약\'을 쓰기 전에 (Q)\'복수의 부메랑\'으로 먼저 견제하고 사거리를 지키며 거리 조절을 하세요. (W)\'쇠약\'은 둔화라 (E)\'영웅의 비상\'은 그대로 쓸 수 있으니, 걸리면 지형을 타고 거리를 벌리는 데 사용해요.', lv6: '나서스의 (R)\'사막의 분노\'가 켜지면 공격 범위와 체력이 늘어나니 정면 싸움은 피하세요. 나서스의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하면 효과적으로 킬을 노릴 수 있어요. 라인을 계속 밀어 넣어 나서스가 포탑 근처에서 편하게 (Q)\'흡수의 일격\'을 사용하지 못하게 관리하세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 전투력을 높이세요. 신발은 나서스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 (P)\'영혼의 포식자\'에 의한 체력 회복 효과를 줄이고 킬을 노리세요.' },
    '녹턴': { lv1: '(Q)\'복수의 부메랑\'을 사용해 꾸준히 원거리 공격을 시도하며 압박하세요. 녹턴이 (Q)\'황혼의 인도자\'를 맞춰 이동 속도가 빨라진 상태로 진입하면 빠르게 뒤로 물러나야 해요. (P)\'비열한 싸움\'의 보호막을 활용해 체력 손실을 최소화하며 거리를 유지하세요.', lv3: '녹턴이 (E)\'말할 수 없는 공포\'를 걸면 즉시 (E)\'영웅의 비상\'으로 지형을 타고 이동해 연결을 끊으세요. 상대가 (W)\'어둠의 장막\'을 켰을 때는 (Q)\'복수의 부메랑\' 같은 스킬 사용을 잠시 멈추고 기본 공격을 하세요. 적절한 타이밍에 스킬을 섞어 쓰며 상대의 진입 각도를 제한하세요.', lv6: '(R)\'피해망상\'으로 적의 시야가 줄어들면 당황하지 말고 지형 근처에서 (E)\'영웅의 비상\'을 사용할 준비를 하세요. 녹턴이 재사용으로 적 챔피언에게 날아와 공격하면 피하기 어려우니, 체력이 낮을 때는 미리 거리를 두고 빠질 길을 확보하세요. 돌격이 끝난 뒤 체력이 낮은 상대는 (R)\'인과응보\'로 마무리하고, 라인을 밀어두고 정글러와 함께 협공하세요.', item: '판금 장화와 크라켄 학살자를 가세요. 판금 장화로 상대 기본 공격 피해를 줄이고 크라켄 학살자의 공격 속도와 추가 피해로 화력을 높이기 위해서예요.', spell: '점멸과 점화. 점화로 녹턴의 (P)\'그림자 칼날\' 회복 효과를 억제하고 확실하게 킬을 내기 위해서예요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩과 (Q)\'학살\'의 회복력 때문에 근접전에서 매우 강해요. (Q)\'복수의 부메랑\'을 활용해 거리 조절을 하며 짤짤이 딜교환을 하시고, (Q)\'학살\'의 도끼날 범위 밖에서 움직이며 체력을 깎으세요. 1~2레벨에 무리하게 붙었다가는 금방 체력이 빠지니 주의하세요.', lv3: '다리우스가 (E)\'포획\'으로 끌어당기면 곧바로 연계 공격이 들어오니 사거리 밖에서 대기하세요. (E)\'포획\'이 빠진 것을 확인한 뒤 (E)\'영웅의 비상\'으로 진입해 빠르게 공격하고 빠지는 패턴을 반복하세요. (W)\'마비의 일격\'의 둔화에 걸리면 위험하니 거리 유지에 집중하며 (Q)\'복수의 부메랑\'으로 견제하세요.', lv6: '(R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 높을 때 치명적이니 출혈이 쌓이기 전에 빠르게 거리를 벌리세요. 다리우스의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 마무리하는 구도를 만드세요. (E)\'포획\'이 빗나간 타이밍에 (E)\'영웅의 비상\'으로 기동성을 활용해 정글러의 개입을 유도하거나 킬각을 잡으세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 다리우스의 기본 공격 피해를 줄여주고, 몰락한 왕의 검은 체력 비례 피해와 공격 속도로 지속 딜링을 도와줘요.', spell: '점멸과 점화를 추천해요. 점화로 다리우스의 (Q)\'학살\' 회복량을 줄이고 킬각을 잡을 때 유용하게 사용하세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 일직선으로 사용하여 견제하므로 미니언 뒤에 서서 피해를 줄이세요. (Q)\'복수의 부메랑\'을 활용해 적절한 거리에서 맞대응하며 성장에 집중해요. 1~2레벨에는 라이즈의 마나 소모를 유도하며 안정적으로 파밍하세요.', lv3: '라이즈가 (E)\'주문 전이\'를 맞힌 후 (W)\'룬 감옥\'으로 속박하는 것을 조심해야 해요. 라이즈의 (W)\'룬 감옥\'이 빠진 타이밍에 (E)\'영웅의 비상\'으로 진입하여 (P)\'비열한 싸움\'의 보호막을 활용해 싸우세요. (Q)\'복수의 부메랑\'을 맞히며 거리를 조절하면 효율적으로 싸울 수 있어요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용하면 다른 곳으로 이동할 수 있으니 무리하게 쫓아가지 마세요. 라이즈의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하면 확실하게 킬을 낼 수 있어요. 라이즈가 궁극기를 통해 합류할 수 있으니 라인을 너무 깊게 밀지 않도록 주의해요.', item: '헤르메스의 발걸음을 선택해 라이즈의 마법 피해와 속박 지속시간을 줄이세요. 첫 코어 아이템으로는 공격 속도와 피해를 높여주는 크라켄 학살자를 추천해요.', spell: '점멸과 점화를 추천해요. 라이즈가 (W)\'룬 감옥\'과 (E)\'주문 전이\'로 몰아붙일 때 점멸로 위치를 빼낼 수 있고, 점화는 (R)\'인과응보\' 뒤 마무리 피해를 더해 줘요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 근접 거리에서 강하게 압박해요. (Q)\'복수의 부메랑\'으로 거리를 유지하며 체력을 깎아두는 것이 중요해요. (E)\'전기 작살\'에 맞아 둔화되면 화염 범위에서 벗어나기 어려우니 작살이 날아오는 선을 피해 움직이세요.', lv3: '럼블이 (W)\'고철 방패\'를 사용하면 피해를 흡수하므로 방패가 사라진 시점에 (E)\'영웅의 비상\'으로 진입하세요. 럼블이 (E)\'전기 작살\'로 둔화를 걸고 (Q)\'화염방사기\'로 몰아붙일 수 있으니 열기가 높은 상태에서는 맞대결을 피해야 해요. (Q)\'복수의 부메랑\'을 맞혀 이동 속도를 얻으며 거리 조절을 하세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 사용하면 불타는 궤적 위에서 싸우지 말고 즉시 옆으로 피하세요. 럼블의 체력이 낮을 때 (R)\'인과응보\'를 사용하면 잃은 체력 비례 피해로 킬을 노리기 좋아요. 럼블의 궁극기는 정글러와의 협공이 강력하니 라인을 밀 때는 항상 조심하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 전투 지속력을 높이세요. 신발은 마법 저항력을 얻기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 럼블이 (W)\'고철 방패\'로 버티는 상황에서 점화로 마무리 피해를 입히면 좋아요.' },
    '레넥톤': { lv1: '1~2레벨 구간에는 (Q)\'복수의 부메랑\'을 활용해 거리를 유지하며 지속적으로 견제해요. 레넥톤이 (Q)\'양떼 도륙\'으로 체력을 회복하며 다가오는 타이밍을 피해 미니언을 챙기세요. 레넥톤의 분노가 쌓이기 전까지는 평타 교전을 피하며 사거리를 지키는 것이 중요해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 들어오며 (W)\'무자비한 포식자\'로 기절을 노리는 구도를 조심하세요. 기절을 맞지 않도록 주의하며 (E)\'영웅의 비상\'을 사용해 빠르게 거리를 벌리거나 위치를 잡아야 해요. 레넥톤의 분노가 높을 때는 (W)\'무자비한 포식자\'의 기절 시간이 길어지니 (Q)\'복수의 부메랑\'으로 멀리서 피해를 입히세요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 늘리고 분노를 얻으면 정면 승부를 피하고 거리를 두세요. 레넥톤의 체력이 낮아진 것을 확인했다면 (R)\'인과응보\'를 사용해 잃은 체력 비례 피해로 확실하게 마무리하세요. (E)\'영웅의 비상\'으로 지형을 이용해 레넥톤의 (E)\'자르고 토막내기\' 추격으로부터 벗어나며 라인을 관리하세요.', item: '첫 코어로 징수의 총을 선택해 킬 캐치 능력을 높이세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복 효과를 감소시켜 교전에서 이득을 보세요.' },
    '렝가': { lv1: '(Q)\'복수의 부메랑\'을 사용하여 렝가의 체력을 조금씩 깎으며 거리를 유지하세요. 렝가가 (E)\'올가미 투척\'으로 둔화를 걸며 접근하지 못하도록 수풀 근처에서의 거리 조절이 중요해요.', lv3: '렝가가 (E)\'올가미 투척\'을 던질 때는 미니언 뒤에 숨어 둔화를 피하는 것이 중요해요. 렝가의 접근을 허용했다면 (E)\'영웅의 비상\'을 사용해 지형을 타고 빠르게 거리를 벌리세요.', lv6: '렝가가 (R)\'사냥의 전율\'을 켜고 위장 상태로 접근할 때는 항상 조심하며 라인을 당겨 관리하세요. 렝가의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 정확히 맞히면 킬을 노릴 수 있어요.', item: '판금 장화와 굶주린 히드라를 선택하세요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 굶주린 히드라는 생명력 흡수로 유지력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 렝가의 (W)\'전투의 포효\'로 인한 체력 회복을 감소시켜 킬을 내기 좋게 도와줘요.' },
    '리븐': { lv1: '리븐이 (Q)\'부러진 날개\'로 접근하며 (P)\'룬 검\'을 활용한 공격이 강한 구간이니 주의하세요. (Q)\'복수의 부메랑\'을 던져 리븐의 체력을 미리 깎으며 사거리 밖에서 견제해요. 리븐이 돌진할 수 있는 거리를 계산하며 거리를 조절하세요.', lv3: '리븐의 (W)\'기 폭발\' 기절을 피하기 위해 (E)\'영웅의 비상\'을 아껴두었다가 적절한 순간에 사용하세요. 리븐이 (E)\'용맹\'으로 보호막을 얻었을 때는 딜교환을 멈추고, 보호막이 사라진 뒤에 (Q)\'복수의 부메랑\'을 맞춰요. (Q)\'부러진 날개\'의 마지막 타격으로 인한 에어본에 맞지 않도록 조심하세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜고 사거리가 길어진 상태라면 무리하게 맞붙지 마세요. 리븐의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 킬을 노리는 것이 중요해요. 리븐이 강력하게 몰아칠 때는 (E)\'영웅의 비상\'으로 지형을 이용해 빠르게 이탈하세요.', item: '리븐의 물리 피해를 줄이기 위해 판금 장화를 선택해요. 첫 코어 아이템으로는 몰락한 왕의 검을 구매해 지속적인 전투력을 높여요.', spell: '점멸과 점화를 추천해요. 리븐의 (E)\'용맹\' 보호막이 사라진 순간 점화로 마무리 피해를 입혀요.' },
    '리산드라': { lv1: '리산드라의 (Q)\'얼음 파편\'은 미니언을 꿰뚫고 지나가며 둔화를 걸기 때문에 일직선으로 서지 않도록 조심하세요. (Q)\'복수의 부메랑\'을 던져 거리를 유지하며 체력을 깎고, 1~2레벨에는 상대의 스킬이 빠진 것을 확인한 뒤에 짧게 평타를 섞어주세요.', lv3: '리산드라의 (W)\'서릿발\'은 속박이라 이동과 돌진을 막으니 범위 밖에서 싸우고, 스킬이 빠진 뒤에 (E)\'영웅의 비상\'으로 진입하세요. (Q)\'복수의 부메랑\'이 챔피언에게 적중하면 이동 속도가 증가하니 이를 활용해 (E)\'얼음갈퀴 길\' 위치를 예측하며 대응하세요.', lv6: '리산드라가 (R)\'얼음 무덤\'을 자신에게 사용하면 공격할 수 없는 무적이 되니 무리하게 딜을 넣지 말고 기다리세요. 궁극기가 끝난 직후 체력이 낮은 적에게 (R)\'인과응보\'를 사용하여 마무리할 수 있어요. 적에게 쓰는 (R)\'얼음 무덤\'은 기절이니 진입 전에 거리를 지키고 (E)\'영웅의 비상\'으로 빠질 길을 확인하세요.', item: '마법 피해가 강력한 리산드라를 상대하기 위해 헤르메스의 발걸음을 먼저 갖추세요. 첫 코어 아이템으로는 몰락한 왕의 검을 선택하여 전투 지속력을 높이고 리산드라와 싸울 때 도움이 되게 하세요.', spell: '점멸과 정화를 추천해요. 리산드라의 (W)\'서릿발\'이나 (R)\'얼음 무덤\'으로 인한 군중 제어를 정화로 빠르게 풀고 대응할 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 활용해 거리를 유지하며 마스터 이의 체력을 깎으세요. 마스터 이가 (P)\'2연속 공격\'으로 평타를 치러 붙기 전에 사거리 밖에서 견제하는 것이 중요해요. 무리하게 싸우기보다는 미니언을 먼저 챙기며 거리를 조절하세요.', lv3: '마스터 이가 (W)\'명상\'을 사용하여 체력을 회복하고 피해를 줄이는 동안에는 공격을 멈추고 빠져나오세요. 마스터 이가 (Q)\'일격 필살\'로 진입하면 대상으로 지정할 수 없는 상태가 되니 스킬을 아꼈다가 그가 착지한 후에 (Q)\'복수의 부메랑\'을 맞히세요. (E)\'영웅의 비상\'을 사용해 마스터 이의 공격 사거리에서 빠르게 벗어나세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 사용하면 둔화 효과에 면역이 되므로 억지로 둔화시켜 멈추려 하지 마세요. 마스터 이의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하면 잃은 체력에 비례한 큰 피해로 킬을 노릴 수 있어요. 정글러가 올 때 마스터 이가 (R)\'최후의 전사\'를 켜고 적을 처치해 지속시간을 늘리지 못하게 주의하세요.', item: '첫 코어로 몰락한 왕의 검을 가서 전투 지속력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마스터 이의 (W)\'명상\' 회복량을 줄여야 확실하게 승부할 수 있어요.' },
    '마오카이': { lv1: '(Q)\'복수의 부메랑\'을 활용해 마오카이가 (P)\'마법 흡수\'로 체력을 회복하기 전에 멀리서 견제하며 미니언을 챙기세요. 마오카이가 (Q)\'덤불 주먹\'으로 접근하며 둔화를 걸려고 하면 거리를 조절하여 충격파를 피해야 해요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 도약해 속박을 시도할 때는 대상으로 지정할 수 없으니 스킬을 낭비하지 마세요. 마오카이의 속박이 빠진 뒤 (E)\'영웅의 비상\'을 이용해 거리를 조절하거나 빠르게 딜교환을 시도하세요. 수풀에 설치된 (E)\'묘목 던지기\'가 터지는 범위는 넓으니 수풀 근처에서의 싸움은 조심하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'를 사용하면 벽이 다가오는 방향을 보고 옆으로 움직여 속박을 피하세요. 마오카이의 체력이 낮아진 것을 확인했다면 (R)\'인과응보\'를 사용해 잃은 체력에 비례한 피해로 킬을 노려보세요. 마오카이가 궁극기로 라인을 압박하면 (Q)\'복수의 부메랑\'으로 미니언을 정리하며 웨이브를 관리하세요.', item: '마법 피해를 입히는 마오카이를 상대하기 위해 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템으로는 지속적인 전투 능력을 높여주는 크라켄 학살자를 추천해요.', spell: '점멸과 점화를 추천해요. 마오카이가 진입할 때 점멸로 거리를 조절하고 점화로 체력 회복을 억제하며 킬각을 잡으세요.' },
    '말자하': { lv1: '말자하가 (P)\'공허 태세\' 상태일 때는 받는 피해가 크게 줄고 군중 제어에 면역이니, 먼저 (Q)\'복수의 부메랑\'으로 피해를 입혀 태세를 풀어 주세요. (Q)\'공허의 부름\' 투사체가 날아오는 위치를 확인해 피하고, 평타를 섞어 (P)\'비열한 싸움\' 보호막을 챙기며 거리를 조절하세요.', lv3: '(E)\'재앙의 환상\'이 걸린 상태에서 (W)\'공허의 무리\'가 붙으면 지속 피해가 심하니 무리하지 말고 뒤로 빠지세요. (E)\'영웅의 비상\'으로 빠르게 진입해 (Q)\'복수의 부메랑\'과 평타를 연계하며 (P)\'비열한 싸움\'의 추가 피해를 입히는 짧은 딜교환을 하세요. 상대가 (Q)\'공허의 부름\'을 쓰기 전에 먼저 움직여 침묵에 걸릴 타이밍을 피하세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니, 상대의 궁극기 사거리를 주의하며 (E)\'영웅의 비상\'으로 지형을 활용해 움직이세요. 체력이 낮아진 상대에게 (R)\'인과응보\'를 발사해 마무리하세요. 라인을 밀 때는 (Q)\'복수의 부메랑\'으로 미니언을 정리하며 정글러의 개입에 대비하세요.', item: '마법 저항력과 공격 속도를 제공하는 마법사의 최후를 추천해요. 신발은 (Q)\'공허의 부름\' 침묵 지속 시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 정화로는 (R)\'황천의 손아귀\' 제압을 풀 수 없으니, 점화로 확실한 킬각을 잡으세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하고 (Q)\'지진의 파편\'으로 둔화를 걸며 견제해요. (Q)\'지진의 파편\'은 대상을 직접 지정하므로 미니언 뒤로 숨어도 맞으니 주의하며 (Q)\'복수의 부메랑\'을 활용해 거리를 조절하세요. (P)\'화강암 방패\'가 사라진 틈을 타서 평타와 (Q)\'복수의 부메랑\'으로 압박하면 좋아요.', lv3: '(W)\'천둥소리\'를 사용한 말파이트의 평타는 추가 피해를 주므로 정면에서 무리하게 싸우지 마세요. (E)\'지면 강타\'에 맞으면 공격 속도가 줄어드니 (E)\'영웅의 비상\'으로 빠르게 위치를 옮기며 대응하세요. (Q)\'복수의 부메랑\'을 맞춰 이동 속도를 얻은 뒤 (E)\'영웅의 비상\'을 활용해 짧게 딜교환을 하고 빠지는 것이 안전해요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 상태로 돌진해 상대를 공중으로 띄우며, 맞으면 스킬을 쓸 수 없으니 주의하세요. 말파이트가 궁극기를 사용한 뒤에는 잠시 빈틈이 생기니 (E)\'영웅의 비상\'으로 접근해 (R)\'인과응보\'로 킬각을 노리세요. 정글러가 근처에 있을 때는 말파이트의 궁극기 사거리 안에 오래 머물지 않도록 조심하며 라인을 관리해요.', item: '첫 코어로 몰락한 왕의 검을 선택해 체력이 높은 말파이트를 압박하세요. 신발은 (Q)\'지진의 파편\'과 (E)\'지면 강타\' 같은 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 말파이트의 체력을 깎아 킬각을 잡는 데 도움을 주세요.' },
    '모데카이저': { lv1: '(Q)\'복수의 부메랑\'을 던지며 거리를 유지하고 모데카이저의 (P)\'암흑 탄생\' 오라가 켜지지 않게 평타 교환을 짧게 끊으세요. (Q)\'말살\'은 범위 안의 모든 적을 맞히고 단일 대상에게는 피해가 커지니 사거리 끝 거리를 지키며 파밍하세요.', lv3: '모데카이저의 (E)\'죽음의 손아귀\'는 범위 안의 적을 끌어당기니 사거리 밖에서 견제하고, 스킬이 빠진 뒤에 (E)\'영웅의 비상\'으로 진입하세요. 모데카이저가 (W)\'불멸\'로 보호막을 모았을 때는 억지로 싸우지 말고 (Q)\'복수의 부메랑\'으로 견제하며 기회를 보세요.', lv6: '모데카이저의 (R)\'죽음의 세계\'에 끌려가면 능력치를 뺏기고 고립되니 체력이 낮을 때는 미리 거리를 두세요. (R)\'죽음의 세계\' 안에서는 순간이동이나 궁극기로 빠져나갈 수 없고 수은 장식띠로도 풀 수 없으니, 끌려가기 전에 사거리 밖을 지키세요. (R)\'인과응보\'를 활용해 체력이 낮은 모데카이저를 멀리서 마무리하세요.', item: '헤르메스의 발걸음을 신어서 마법 저항력으로 모데카이저의 마법 피해를 줄이세요. 맬모셔스의 아귀를 첫 코어로 가면 마법 저항력과 생명선 효과 덕분에 모데카이저의 공격을 견디기 쉬워요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'불멸\'의 회복을 억제하면 킬을 내기 쉬워요.' },
    '문도박사': { lv1: '문도 박사의 (Q)\'오염된 뼈톱\'은 처음 맞는 대상에게 날아가니 미니언 뒤에 서서 피해를 피하세요. (Q)\'복수의 부메랑\'을 사용하여 지속적으로 문도 박사를 견제하며 거리를 유지해요. 문도 박사는 (P)\'가고 싶은 데로 간다\'로 체력 재생이 크게 늘어나니 견제를 끊지 말고 꾸준히 이어가세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜고 주변 적에게 피해를 주며 회복하려고 하면 (E)\'영웅의 비상\'으로 거리를 벌리세요. (Q)\'복수의 부메랑\'을 맞히며 압박을 이어가고, 문도 박사가 (E)\'둔기에 의한 외상\'을 사용해 들어올 때는 (E)\'영웅의 비상\'을 사용해 빠르게 거리를 벌려요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용하면 체력 회복과 이동 속도가 크게 늘어나니 무리하게 쫓아가지 마세요. 문도 박사의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 잃은 체력에 비례한 피해로 마무리하세요. 문도 박사의 궁극기가 빠진 타이밍에 라인을 강하게 압박하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 가세요. 문도 박사의 마법 피해를 견디고 높은 체력을 깎기 위해 선택해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 문도 박사의 (R)\'최대 투여량\' 회복을 억제할 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'로 멀리서 견제하며 주도권을 가져가려 해요. (Q)\'복수의 부메랑\'을 던져서 바루스의 체력을 깎으며 압박하세요. 상대의 사거리가 더 기니 무리하게 다가가기보다 (Q)\'꿰뚫는 화살\' 충전이 보일 때 옆으로 피하며 기회를 엿보세요.', lv3: '바루스의 평타로 (W)\'역병 화살\' 중첩이 쌓인 상태에서 (Q)\'꿰뚫는 화살\'을 맞으면 체력 비례 마법 피해가 크게 들어와요. 바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시켜 이동 속도를 늦추면 그 위를 벗어나세요. 상대의 스킬이 빠졌을 때 (E)\'영웅의 비상\'으로 빠르게 파고들어 (Q)\'복수의 부메랑\'과 평타로 딜교환을 하세요.', lv6: '바루스의 (R)\'부패의 사슬\'은 처음 맞은 챔피언을 속박하고 속박 중에는 (E)\'영웅의 비상\'으로도 움직일 수 없으니, 촉수가 날아오는 방향을 보고 미리 옆으로 피하세요. 바루스가 궁극기를 빗맞혔다면 (E)\'영웅의 비상\'으로 지형을 타고 파고들 기회예요. 바루스의 체력이 낮아지면 (R)\'인과응보\'로 강력한 피해를 입혀 처치할 수 있어요.', item: '몰락한 왕의 검을 첫 코어로 올려서 바루스와의 교전 능력을 높이세요. 신발은 상대의 기본 공격 피해를 줄여주는 판금 장화를 선택하세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 사거리 안으로 빠르게 파고들 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 세 번째 공격마다 강한 고정 피해를 입히니 평타를 계속 맞지 않게 주의하세요. (Q)\'복수의 부메랑\'을 던져 베인의 체력을 깎고 이동 속도를 얻어 적절한 거리를 유지하며 파밍해요. 1~2레벨에는 (Q)\'구르기\'로 거리를 좁힌 뒤 강화 평타가 들어오니 짧게 교환하고 빠지세요.', lv3: '베인의 (E)\'선고\'에 맞았을 때 기절하지 않도록 벽에서 떨어진 곳에서 싸우는 것이 중요해요. 베인이 (Q)\'구르기\'를 사용한 직후에 (E)\'영웅의 비상\'으로 빠르게 접근해 (P)\'비열한 싸움\'의 보호막을 얻으며 짧게 딜교환하세요. 베인이 (E)\'선고\'를 낭비했다면 그 틈을 타서 몰아치며 체력을 깎으세요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\'로 투명해지므로 무리하게 쫓기보다 거리 조절에 집중하세요. 베인의 체력이 낮아진 순간에 (R)\'인과응보\'를 발사해 잃은 체력 비례 피해로 마무리하는 것이 핵심이에요. (E)\'영웅의 비상\'으로 빠르게 진입해 킬각을 잡고 정글러의 도움을 받아 압박하세요.', item: '크라켄 학살자로 세 번째 공격마다 추가 피해를 입혀 화력을 높이세요. 신발은 베인의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 빠져나가기 전에 점화의 추가 피해로 확실하게 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 접근해 기절을 걸 수 있으니 거리를 조절하며 (Q)\'복수의 부메랑\'으로 먼저 견제하세요. 초반에는 볼리베어의 기본 공격과 스킬 사용으로 공격 속도가 올라가는 (P)\'무자비한 폭풍\' 중첩을 쌓지 못하게 짧게 교환하고 빠지는 것이 좋아요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남기면 다시 사용하여 체력을 회복하기 전에 (E)\'영웅의 비상\'을 활용해 거리를 벌리세요. (E)\'천공 분열\'은 지정한 위치에 번개가 떨어지니 표시된 범위에서 벗어나 둔화를 피하고 (Q)\'복수의 부메랑\'을 맞춰 지속적인 피해를 입히세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 포탑을 비활성화하며 다이브를 시도할 수 있으니 체력이 낮을 때는 포탑 근처에서 싸우지 마세요. 볼리베어가 궁극기를 사용한 뒤에는 (R)\'인과응보\'로 잃은 체력 비례 피해를 입혀 확실하게 적을 처치하세요.', item: '몰락한 왕의 검을 첫 코어로 올려 맞대결 능력을 높이세요. 신발은 기절 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어의 (W)\'광란의 상처\'로 인한 체력 회복을 줄이기 위해 점화를 사용하세요.' },
    '블라디미르': { lv1: '(Q)\'복수의 부메랑\'의 사거리가 더 기니 거리 조절을 하며 계속해서 견제하세요. 블라디미르의 (Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 맞으므로 체력 관리에 신경 쓰세요. (P)\'비열한 싸움\'의 보호막을 통해 짧은 딜교환에서 이득을 보세요.', lv3: '(E)\'영웅의 비상\'으로 진입할 때 (W)\'피의 웅덩이\'를 쓰면 대상으로 지정할 수 없으니 주의하며 사용하세요. (E)\'선혈의 파도\'는 적 유닛이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. (W)\'피의 웅덩이\'가 빠진 타이밍에 (Q)\'복수의 부메랑\'과 평타를 섞어 강하게 압박하세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안에는 무리하게 붙지 말고 뒤로 물러나세요. 상대의 체력이 낮아졌을 때 (R)\'인과응보\'를 저장해 발사하면 잃은 체력 비례 피해로 마무리할 수 있어요. (E)\'영웅의 비상\'으로 지형을 이용해 빠르게 진입하며 정글러와 함께 킬각을 잡으세요.', item: '마법사의 최후와 헤르메스의 발걸음을 추천해요. 마법 저항력으로 (Q)\'수혈\' 피해를 줄이고 강인함으로 (E)\'선혈의 파도\' 둔화 시간을 줄일 수 있어요.', spell: '점멸과 점화를 추천해요. 블라디미르가 (Q)\'수혈\'로 체력을 회복하는 것을 막아야 확실하게 처치할 수 있어요.' },
    '뽀삐': { lv1: '(Q)\'복수의 부메랑\'으로 뽀삐를 계속 견제하며 거리를 유지하세요. 뽀삐가 (Q)\'망치 강타\'로 만든 둔화 지대 위에서 싸우지 않도록 계속 움직여야 해요. 뽀삐가 (P)\'강철의 외교관\' 방패를 주워 보호막을 얻기 전에 빠르게 평타와 스킬을 섞어 압박하세요.', lv3: '(E)\'영웅의 비상\'을 쓰기 전에 뽀삐가 (W)\'굳건한 태세\'를 먼저 켜는지 확인하세요. (W)\'굳건한 태세\'가 켜진 상태에서 진입하면 돌진이 막히고 느려지니, 스킬이 빠진 것을 확인하고 진입해 교환하세요. 뽀삐가 (E)\'용감한 돌진\'으로 밀어붙여 지형에 부딪히면 기절하니 벽 근처에서는 항상 주의해야 해요.', lv6: '뽀삐가 (R)\'수호자의 심판\'을 사용해 멀리 날려버리면 (R)\'인과응보\' 탄환을 맞히기 어려우니 거리 조절에 집중하세요. (E)\'영웅의 비상\'으로 빠르게 진입해 딜을 넣은 뒤, 뽀삐의 체력이 낮아졌을 때 (R)\'인과응보\'를 발사해 마무리하세요. 정글러가 올 때 뽀삐의 밀어내기 스킬들이 빠졌는지 보고 진입하는 것이 좋아요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 뽀삐를 효과적으로 깎으세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 초반 교전에서 뽀삐의 체력을 빠르게 깎아 킬각을 잡으세요.' },
    '사이온': { lv1: '사이온이 (E)\'학살자의 포효\'를 쓰면 미니언이 밀려나며 뒤까지 맞으니 미니언 뒤에 숨지 마세요. (Q)\'복수의 부메랑\'을 계속 던져 체력을 깎고 (P)\'비열한 싸움\'의 보호막을 챙기며 거리를 유지하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 모습이 보이면 옆으로 빠르게 피해서 헛치게 만드세요.', lv3: '사이온이 (W)\'영혼의 용광로\'로 보호막을 켜면 재시전 폭발 피해가 크니 잠시 물러나세요. (E)\'학살자의 포효\'를 피한 뒤 (E)\'영웅의 비상\'으로 진입해 빠르게 공격하고 빠지는 딜교환을 반복하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전할 때 (Q)\'복수의 부메랑\'을 던져 이동 속도를 얻고 범위를 벗어나세요.', lv6: '사이온이 (R)\'멈출 수 없는 맹공\'으로 돌진해 오면 저지 불가 상태이므로 미리 옆으로 비켜서서 피하세요. 체력이 낮아진 사이온에게 (R)\'인과응보\'를 사용해 확실하게 마무리하고 빠르게 이탈하세요. 처치 후에도 (P)\'영광스러운 죽음\'으로 되살아나 공격하니 완전히 사라질 때까지 거리를 두세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 많은 사이온에게 효율적인 피해를 입히세요. 신발은 (Q)\'대량 학살 강타\'의 기절과 (E)\'학살자의 포효\' 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온이 라인을 강하게 밀어내므로 순간이동으로 빠르게 복귀해 손실을 줄이세요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'를 던져 둔화를 묻히고 (P)\'페트리사이트 폭발\' 평타로 딜교를 시도해요. (Q)\'복수의 부메랑\'으로 멀리서 견제하고, 부메랑이 적중했을 때 얻는 이동 속도로 사슬의 중심 폭발 지점에서 벗어나세요. 1~2레벨에는 사일러스의 체력이 낮으니 거리 조절만 잘하며 계속 괴롭히세요.', lv3: '사일러스가 (E)\'도주 / 억압\'으로 진입해 공중으로 띄우려 할 때 옆으로 무빙하여 피하세요. (W)\'국왕시해자\'의 회복량이 상당하니 이 스킬이 빠진 것을 확인한 뒤 (E)\'영웅의 비상\'으로 빠르게 진입해 딜교환을 하세요. (Q)\'복수의 부메랑\'으로 먼저 체력을 깎아두면 (W)\'국왕시해자\'의 효율을 낮출 수 있어요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'인과응보\'를 훔쳐 사용하면 체력이 낮을 때 치명적이니 주의하세요. 사일러스의 체력이 어느 정도 빠졌을 때 (R)\'인과응보\'를 충전해 발사하여 마무리하는 것이 좋아요. (E)\'영웅의 비상\'의 재사용 대기시간 초기화를 노려 킬각을 잡되, 훔친 궁극기에 맞지 않게 거리를 두세요.', item: '몰락한 왕의 검을 첫 코어로 가서 지속 딜링과 체력 회복 능력을 챙기세요. 신발은 사일러스의 마법 피해를 줄이고 강인함으로 군중 제어 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제해야 해요.' },
    '세주아니': { lv1: '1~2레벨 구간에는 (Q)\'복수의 부메랑\'을 활용해 멀리서 체력을 깎으며 주도권을 가져와요. 상대가 (Q)\'혹한의 맹습\'으로 돌진해 들어오려고 하면 무빙으로 피하며 거리를 유지하세요. 상대의 (P)\'혹한의 분노\'로 인해 방어력이 높아진 시점에는 무리한 평타 교전을 피해야 해요.', lv3: '3레벨 이후에는 (W)\'혹한의 서릿발\'에 맞아 둔화되지 않도록 주의하며 (Q)\'복수의 부메랑\'을 맞히는 데 집중해요. 상대의 (Q)\'혹한의 맹습\'이 빠진 것을 확인한 뒤에 (E)\'영웅의 비상\'을 사용해 빠르게 진입하여 딜교환을 시도하세요. (E)\'만년 서리\'의 기절을 맞지 않게 거리를 조절하는 것이 중요해요.', lv6: '6레벨 이후에는 (R)\'빙하 감옥\'에 맞으면 행동이 제약되니 항상 상대의 위치를 확인하며 대응하세요. 상대 체력이 낮아지면 (R)\'인과응보\'를 사용하여 잃은 체력 비례 피해로 확실하게 킬을 노려요. 정글러가 근처에 있다면 (E)\'영웅의 비상\'으로 빠르게 지형을 타고 도망치거나 합류를 준비하세요.', item: '헤르메스의 발걸음과 몰락한 왕의 검을 선택해요. 헤르메스의 발걸음은 강인함을 제공해 세주아니의 군중 제어 지속시간을 줄여줘요. 몰락한 왕의 검은 공격 속도와 생명력 흡수를 제공해요.', spell: '점멸과 점화. 상대의 체력을 빠르게 낮추고 (R)\'인과응보\'로 마무리하기 좋아요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 켜고 달려들며 최대 체력 비례 피해를 입히니 1~2레벨에 무리하게 맞대결하지 마세요. (Q)\'복수의 부메랑\'으로 거리를 유지하며 세트의 체력을 먼저 깎아두는 것이 좋아요. 세트는 받은 피해를 (W)\'강펀치\'의 투지로 저장하니 길게 싸우지 말고 짧게 치고 빠지며 견제하세요.', lv3: '세트가 (E)\'안면 강타\'를 사용해 양옆의 적을 끌어당기려 할 때 미니언 사이에 서지 않도록 주의하세요. (W)\'강펀치\'의 보호막과 고정 피해가 위협적이니 세트의 투지가 충분히 쌓이기 전에 (E)\'영웅의 비상\'으로 위치를 잡으세요. 세트의 스킬을 피하며 (Q)\'복수의 부메랑\'으로 압박을 이어가세요.', lv6: '세트의 (R)\'대미 장식\'에 붙잡혀 제압 상태가 되면 스킬을 사용할 수 없으니 주의해야 해요. 세트의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 확실하게 마무리하세요. 세트가 붙잡을 수 있는 거리를 지키고, 라인을 너무 깊게 밀지 말고 정글러의 위치를 확인하세요.', item: '몰락한 왕의 검을 첫 코어로 올려 생명력 흡수를 활용하세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. (P)\'투기장의 투지\'로 얻는 체력 회복을 점화로 억제하며 싸우세요.' },
    '쉔': { lv1: '(Q)\'복수의 부메랑\'을 던져서 쉔의 체력을 깎으며 거리 조절을 하세요. 쉔이 (Q)\'황혼 강습\'을 사용할 때 기의 검이 지나가는 길목을 피해 맞교환을 최소화해요. 쉔이 스킬을 쓰면 (P)\'기 보호막\'이 생기니 보호막이 사라진 뒤에 평타를 섞어주세요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼치면 기본 공격이 차단되니 (Q)\'복수의 부메랑\'으로 견제하며 기다리세요. 쉔이 (E)\'그림자 돌진\'으로 들어와 도발을 걸면 스킬을 쓸 수 없으니 주의해야 해요. 도발이 빠진 직후에 (E)\'영웅의 비상\'을 사용하여 빠르게 접근하거나 거리를 조절하세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용해 다른 라인으로 이동하면 라인을 강하게 밀어 포탑 압박을 시도하세요. 쉔의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 잃은 체력 비례 피해로 마무리하는 것이 중요해요. 쉔의 (E)\'그림자 돌진\'이 빠진 것을 확인한 뒤 (E)\'영웅의 비상\'으로 지형을 타며 공격을 이어가세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 쉔의 높은 체력을 효과적으로 깎으세요. 신발은 쉔의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 쉔이 (E)\'그림자 돌진\'으로 진입할 때 점멸로 위치를 조절하고, 점화는 체력이 낮아진 쉔을 마무리하는 피해를 더해 줘요.' },
    '쉬바나': { lv1: '(Q)\'복수의 부메랑\'을 사용하여 쉬바나가 접근하기 전에 지속적으로 체력을 깎으세요. 쉬바나가 (W)\'지옥불 방패\'로 이동 속도를 얻어 빠르게 다가오면 뒤로 물러나며 거리를 유지하는 것이 중요해요. 첫 웨이브부터 원거리 공격의 이점을 살려 압박하세요.', lv3: '(E)\'용암 분출\'의 둔화에 맞지 않도록 무빙하며 (Q)\'복수의 부메랑\'으로 견제하세요. 쉬바나가 (W)\'지옥불 방패\'의 보호막을 켜고 진입하면 (E)\'영웅의 비상\'으로 빠르게 거리를 벌리거나 위치를 잡으세요. 상대의 핵심 스킬이 빠진 뒤에 기본 공격으로 패시브 보호막을 챙기며 딜교환을 해요.', lv6: '(R)\'용의 강림\'의 저지 불가 돌진과 적을 달아나게 하는 효과에 맞지 않도록 각별히 주의하세요. 쉬바나가 변신해 공격적으로 나올 때는 (E)\'영웅의 비상\'으로 지형을 이용해 회피하며 시간을 끄세요. 체력이 낮아진 적에게 (R)\'인과응보\'를 정확히 맞춰 마무리하며 킬각을 잡으세요.', item: '몰락한 왕의 검과 헤르메스의 발걸음을 추천해요. 체력이 높은 상대에게 효과적으로 피해를 입히고 마법 저항력과 강인함으로 둔화 시간을 줄이기 위해서예요.', spell: '점멸과 점화. 낮은 체력의 적을 확실하게 처치하고 쉬바나의 체력 회복을 억제하기 위해 선택하세요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'복수의 부메랑\'을 활용해 스웨인이 접근하기 전에 거리를 유지하며 타격하세요. 스웨인이 영혼 조각을 모으기 전인 초반에 피해를 입혀 두는 것이 중요해요.', lv3: '스웨인이 (E)\'속박명령\'을 사용하면 파동이 돌아오는 경로를 보고 (E)\'영웅의 비상\'을 사용하여 위치를 옮기세요. (E)\'속박명령\'에 맞으면 이동만 막히지만 (Q)\'복수의 부메랑\'은 계속 사용할 수 있어요. (W)\'제국의 눈\'에 맞으면 모습이 드러나니 거리 조절에 유의하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용해 변신하면 주변에서 체력을 흡수하니 근접 교전을 피하세요. 스웨인의 체력이 낮아진 시점에 (R)\'인과응보\'를 사용하여 마무리하는 것이 좋아요. 스웨인이 변신하면 (E)\'영웅의 비상\'으로 거리를 벌리며 라인 관리를 하고 정글러를 부르세요.', item: '굶주린 히드라를 첫 코어로 선택하여 생명력 흡수와 라인 클리어를 챙기세요. 신발은 스웨인의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 스웨인은 (P)\'굶주린 새떼\'와 (R)\'악의 승천\'으로 체력을 회복하니 점화로 회복량을 줄여 주세요.' },
    '스카너': { lv1: '(Q)\'복수의 부메랑\'으로 끊임없이 견제하며 스카너의 접근을 막으세요. (Q)\'부서진 대지/지반 돌출\'의 투사체 사거리 밖에서 짧은 딜교환을 반복하며 체력을 깎는 것이 중요해요. 첫 웨이브부터 거리를 유지하며 상대가 다가오지 못하게 하세요.', lv3: '스카너가 (W)\'대지의 수호자\'로 보호막을 켰을 때는 딜교환을 피하고 보호막이 사라질 때까지 기다리세요. (E)\'이쉬탈의 격돌\'에 끌려 벽에 부딪히지 않도록 (E)\'영웅의 비상\'을 사용해 빠르게 지형을 이동하며 거리 조절을 하세요. 상대의 돌진기가 빠진 직후에 공격을 시도해요.', lv6: '스카너의 (R)\'꿰뚫기\'는 제압 효과이므로 정화로 풀 수 없으니 항상 거리를 넉넉히 두세요. 상대의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 저장해 발사하면 확실하게 처치할 수 있어요. (E)\'영웅의 비상\'으로 벽을 넘나들며 정글러의 개입을 피하고 안전하게 라인을 관리하세요.', item: '판금 장화와 몰락한 왕의 검을 가세요. 판금 장화는 기본 공격으로 받는 피해량을 줄여줘요. 몰락한 왕의 검은 생명력 흡수 효과가 있어 유지력에 도움을 줘요.', spell: '점멸과 순간이동을 추천해요. (R)\'인과응보\'의 긴 사거리를 활용하면서 라인 복귀와 합류를 빠르게 하기 위해서예요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 남기며 라인을 밀어넣으니 독구름 위에서는 싸우지 마세요. (Q)\'복수의 부메랑\'을 활용해 멀리서 신지드의 체력을 깎으며 미니언 막타를 챙겨요. 신지드가 (P)\'독성 급류\'로 빠르게 다가오면 거리를 벌려 피해를 줄이세요.', lv3: '신지드의 (W)\'초강력 접착제\'에 닿으면 (E)\'영웅의 비상\'을 사용할 수 없으니 위치 선정에 주의하세요. 신지드가 (E)\'던져넘기기\'로 던질 때 접착제 위로 떨어지지 않도록 조심하며 (Q)\'복수의 부메랑\'으로 먼저 견제해요. 신지드의 (W)\'초강력 접착제\'가 빠진 직후에 (E)\'영웅의 비상\'으로 진입하여 딜교환을 하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 마시면 체력 재생과 방어력이 높아지니 정면 대결은 피하세요. 신지드의 체력이 낮아진 것을 확인하면 (R)\'인과응보\'를 사용하여 확실하게 처치하세요. 신지드가 라인을 밀며 들어올 때 (E)\'영웅의 비상\'으로 도주 경로를 확보하는 것이 중요해요.', item: '헤르메스의 발걸음을 가서 신지드의 마법 피해를 견디고 강인함을 챙기세요. 굶주린 히드라를 첫 코어로 선택해 전투 중 생명력을 흡수하며 버티세요.', spell: '점멸과 정화를 추천해요. 신지드의 (W)\'초강력 접착제\'가 거는 둔화나 (E)\'던져넘기기\' 이후에 발생하는 속박을 빠르게 해제할 수 있어요.' },
    '신짜오': { lv1: '(Q)\'복수의 부메랑\'을 활용하여 최대한 멀리서 신짜오를 견제하며 미니언을 챙겨요. 신짜오가 (Q)\'삼조격\'의 세 번째 공격으로 공중으로 띄우려 하면 거리를 벌려 대응하세요. 초반에는 신짜오의 근접 전투력이 강하므로 무리하게 붙기보다 거리를 유지하는 것이 좋아요.', lv3: '신짜오가 (W)\'풍전참뢰\'를 맞히고 (E)\'무쌍돌격\'으로 돌진해오는 타이밍을 조심해야 해요. (Q)\'복수의 부메랑\'을 맞히며 거리를 유지하고 신짜오의 돌진을 (E)\'영웅의 비상\'으로 피하며 딜교환을 하세요. 신짜오는 (P)\'결심\'으로 세 번째 기본 공격마다 체력을 회복하니 평타 교환을 길게 가져가지 마세요.', lv6: '신짜오가 (R)\'현월수호\'를 사용하면 원거리에서 공격을 받지 않는 상태가 되니 (R)\'인과응보\'를 아껴두세요. 신짜오의 궁극기 효과가 끝난 뒤 체력이 낮은 상태라면 (R)\'인과응보\'를 사용하여 확실하게 마무리해요. 정글러가 근처에 있다면 (E)\'영웅의 비상\'으로 빠르게 지형을 타며 위치를 잡으세요.', item: '판금 장화와 징수의 총을 선택해요. 신짜오의 기본 공격 피해를 줄이고 징수의 총으로 적을 처치하기 위해서예요.', spell: '점멸과 점화. 신짜오의 돌진을 점멸로 피하고 점화로 마무리 피해를 높이기 위해서예요.' },
    '아이번': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 사용하여 아이번의 체력을 깎으며 압박하세요. 아이번이 (Q)\'덩굴뿌리\'를 던져 속박시키려 할 때 무빙으로 피하며 거리를 유지하는 것이 중요해요. 첫 웨이브부터 적극적으로 견제하며 상대의 진입 각을 차단하세요.', lv3: '(E)\'영웅의 비상\'으로 빠르게 진입해 딜교환을 시도하되, (E)\'보호의 씨앗\'이 터지며 발생하는 둔화에 주의하세요. 아이번이 (W)\'수풀 가꾸기\'로 수풀에서 추가 마법 피해를 얻기 전에 빠르게 공격하고 빠져나와야 해요. 상대의 (Q)\'덩굴뿌리\'가 빠진 타이밍에 들어가서 체력을 깎으세요.', lv6: '(R)\'인과응보\'를 충전해 체력이 낮아진 아이번을 마무리하는 구도를 만드세요. 아이번이 (R)\'데이지!\'를 소환하면 데이지의 충격파로 공중에 뜰 수 있으니 (E)\'영웅의 비상\'으로 거리를 조절하며 싸워요. 라인을 밀어넣고 정글러의 개입에 대비해 시야를 확인하세요.', item: '헤르메스의 발걸음과 독사의 송곳니를 추천해요. 독사의 송곳니로 (E)\'보호의 씨앗\' 보호막의 효과를 줄이고, 헤르메스의 발걸음으로 속박과 둔화 지속시간을 줄일 수 있어요.', spell: '점멸과 점화를 선택하세요. 점멸은 (E)\'영웅의 비상\'과 함께 사용하여 빠르게 진입하거나 (Q)\'덩굴뿌리\'를 피하기 좋고, 점화는 (R)\'인과응보\'와 함께 적을 확실히 처치하기 위해 필요해요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'으로 견제하며 거리를 벌릴 때 (Q)\'복수의 부메랑\'을 던져 피해를 입히며 파밍해요. 상대의 (W)\'일어나라!\' 사거리에 무작정 들어가지 말고 미니언을 끼고 거리를 조절하며 버텨요. (Q)\'복수의 부메랑\'이 챔피언에게 적중해 이동 속도를 얻는 타이밍을 활용해 적극적으로 딜교환을 시도해요.', lv3: '아지르의 (E)\'신기루\' 보호막이 빠진 것을 확인한 뒤 (E)\'영웅의 비상\'으로 빠르게 접근해 딜교환을 해요. 아지르의 (Q)\'사막의 맹습\'에 맞아 둔화되지 않도록 움직임에 주의하며 (Q)\'복수의 부메랑\'을 맞춰 이동 속도를 확보해요. (E)\'영웅의 비상\'이 챔피언에게 충돌하지 않도록 지형을 잘 활용하여 진입해야 해요.', lv6: '아지르가 (R)\'황제의 진영\'으로 밀쳐내려 할 때 (E)\'영웅의 비상\'을 활용해 예측하기 힘든 경로로 파고들어요. 상대의 체력이 낮아지면 (R)\'인과응보\'를 사용하여 확정적인 킬각을 노리되 아지르의 반격을 조심해요. 라인을 빠르게 밀어 넣고 아지르가 압박을 느끼게 만들며 정글러의 개입을 유도해요.', item: '헤르메스의 발걸음과 굶주린 히드라를 가요. 아지르의 마법 피해와 군중 제어에 대응하기 위해 헤르메스의 발걸음을 선택하고, 강력한 공격력과 생명력 흡수를 위해 굶주린 히드라를 구매해요.', spell: '점멸과 점화. 아지르의 거리 조절을 무너뜨리거나 체력이 낮은 적을 처치하기 위해 사용해요.' },
    '아칼리': { lv1: '(Q)\'복수의 부메랑\'을 던져 거리 조절을 하며 계속 견제하세요. 아칼리가 (Q)\'오연투척검\'으로 둔화를 걸고 (P)\'암살자의 표식\' 원 경계를 넘으며 평타를 노릴 때 뒤로 물러나세요. 초반에는 짧은 딜교환으로 체력을 깎아 두는 것이 좋아요.', lv3: '아칼리가 (W)\'황혼의 장막\'을 쓰면 대상 지정이 안 되니, (Q)\'복수의 부메랑\' 같은 투사체 스킬로 피해를 입히세요. (E)\'표창곡예\'에 맞아 표식이 남으면 아칼리가 돌진해 들어오니 (E)\'영웅의 비상\'으로 빠르게 거리를 벌리세요. (P)\'비열한 싸움\'으로 얻는 보호막을 통해 상대의 진입 피해를 흡수하세요.', lv6: '(R)\'무결처형\'으로 아칼리가 빠르게 진입해 체력을 깎으려 하니 체력 관리에 유의하세요. (R)\'인과응보\'는 잃은 체력에 비례해 피해를 입히므로 아칼리의 체력이 낮을 때 조준해 발사하세요. 아칼리가 연막 속에 있으면 조준하기 어려울 수 있으니 연막 밖으로 나온 순간을 노리세요.', item: '크라켄 학살자를 첫 코어로 선택해 공격 속도와 피해량을 높이세요. 신발은 아칼리의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎아 (R)\'인과응보\'의 마무리 피해를 높이세요.' },
    '아트록스': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 활용해 거리를 유지하며 아트록스의 (Q)\'다르킨의 검\' 끝자락을 피하세요. 아트록스가 (P)\'사신 태세\'로 평타를 통해 체력을 회복하는 구간은 피하는 것이 좋아요. 근접전이 벌어지는 구간에서는 아트록스의 힘이 강해지니 주의해야 해요.', lv3: '아트록스가 (W)\'지옥사슬\'을 쓰면 중앙으로 끌려가지 않도록 빠르게 범위 밖으로 나가세요. (Q)\'다르킨의 검\'이 빠진 빈틈을 이용해 (E)\'영웅의 비상\'으로 진입하거나 거리 조절을 해요. 아트록스의 (E)\'파멸의 돌진\'에 휘말리지 않으면서 (Q)\'복수의 부메랑\'을 적중시키는 것이 중요해요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하면 공격력과 체력 회복량이 늘어나니 싸움을 피하세요. 아트록스의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 킬을 노리는 것이 효과적이에요. 정글러가 근처에 있다면 아트록스가 처치 관여로 궁극기를 연장하지 못하게 주의하세요.', item: '전투력을 높이기 위해 몰락한 왕의 검을 첫 코어로 올려요. 신발은 아트록스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화는 아트록스의 체력 회복 효과를 줄이는 데 도움을 줘요.' },
    '암베사': { lv1: '(Q)\'복수의 부메랑\'으로 계속 견제하며 암베사가 (Q)\'교활한 휩쓸기\'의 반원 범위로 파고들지 못하게 거리 조절을 하세요. (P)\'용사냥개의 발걸음\'으로 인한 갑작스러운 돌진 평타가 들어오면 빠르게 뒤로 물러나며 딜교환을 짧게 끝내세요.', lv3: '암베사가 (W)\'배척\'의 보호막을 켰을 때는 공격을 멈춰서 피해량이 증가하는 것을 막으세요. (E)\'찢어 가르기\'의 둔화에 걸렸을 때 (E)\'영웅의 비상\'으로 빠르게 지형에 고정해 거리 조절을 하며 공격하세요. (Q)\'복수의 부메랑\'을 먼저 맞혀 이동 속도를 얻은 뒤 평타를 빠르게 넣어 (P)\'비열한 싸움\'의 보호막을 얻으세요.', lv6: '암베사의 (R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적 챔피언에게 순간이동해 제압하니 정글러와 떨어져 홀로 깊이 나가 있지 마세요. 제압당하면 (E)\'영웅의 비상\'이나 (R)\'인과응보\'를 쓸 수 없으니 주의하고, 암베사의 체력이 낮아지면 (R)\'인과응보\'로 빠르게 마무리하세요. 정글러가 개입할 때 (E)\'영웅의 비상\'으로 벽을 넘어 빠르게 탈출하거나 합류하세요.', item: '징수의 총을 첫 코어로 가서 물리 관통력과 처치 능력을 높여 암베사의 체력을 빠르게 깎으세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사는 (R)\'공개 처형\'의 기본 지속 효과로 체력을 회복하므로 점화의 치유 감소 효과가 중요해요.' },
    '애니비아': { lv1: '애니비아의 (Q)\'냉기 폭발\'은 구체가 끝에서 터지면 기절을 유발하니 구체가 멈추는 지점을 피해 이동하세요. (Q)\'복수의 부메랑\'을 미니언에 맞혀 사거리를 늘리며 멀리서 견제하세요. 애니비아가 스킬을 쓰기 전에 미리 거리를 조절하며 압박하세요.', lv3: '애니비아가 (Q)\'냉기 폭발\'을 맞춘 후 (E)\'동상\'을 연계하면 피해가 매우 커지니 주의하세요. (W)\'결정화\' 벽이 생성되면 이동 경로가 막히므로 벽이 생기기 전이나 벽이 사라진 뒤에 접근하세요. (E)\'영웅의 비상\'으로 지형을 활용해 애니비아의 스킬 사정권 밖에서 딜교환을 시도하세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 사용하면 둔화와 피해가 지속되니 장판 밖에서 진입하세요. 체력이 낮은 애니비아에게 (R)\'인과응보\'를 사용하여 마무리하되, (P)\'환생\'으로 알이 되면 즉시 공격해 체력을 회복하지 못하게 하세요. 애니비아의 (W)\'결정화\'가 빠진 타이밍에 정글러와 함께 압박하여 킬을 노리세요.', item: '헤르메스의 발걸음을 신어서 마법 저항력을 높이고 강인함으로 (Q)\'냉기 폭발\'의 기절과 둔화 시간을 줄이세요. 징수의 총을 첫 코어로 선택해 체력이 낮은 적을 확실히 처치하세요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'로 인한 기절을 정화로 빠르게 풀고 대응할 수 있어요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 맞춰 회오리바람을 만들려 할 때 거리를 유지하며 (Q)\'복수의 부메랑\'을 던져 견제하세요. 야스오의 (P)\'낭인의 길\' 보호막은 이동을 통해 쉽게 채워지니 첫 웨이브 때 짧은 평타로 보호막을 먼저 제거하는 것이 좋아요.', lv3: '야스오가 (W)\'바람 장막\'을 펼치면 (Q)\'복수의 부메랑\'이 막히므로 장막이 사라질 때까지 스킬을 아끼세요. 야스오가 (E)\'질풍검\'으로 미니언 사이를 돌진하며 다가온다면 (E)\'영웅의 비상\'을 사용해 지형으로 빠르게 거리를 벌리며 대응하세요.', lv6: '야스오의 (Q)\'강철 폭풍\'에 맞아 공중에 뜨면 (R)\'최후의 숨결\'로 이어지니 회오리바람을 피하는 무빙에 집중하세요. 야스오의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 사용하여 확실하게 처치하고, (E)\'영웅의 비상\'을 활용해 야스오가 (E)\'질풍검\'으로 도망가는 것을 따라잡으세요.', item: '첫 코어 아이템으로 징수의 총을 선택하여 처치 능력을 높이세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오가 (E)\'질풍검\'으로 빠져나가려 할 때 점멸로 거리를 좁히고, 점화는 (R)\'인과응보\' 뒤 마무리 피해를 더해 줘요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 평타 사거리를 늘려 견제하며 (P)\'바위 피부\'로 체력을 회복해요. (Q)\'복수의 부메랑\'을 던져 거리를 유지하며 오공이 다가오지 못하게 계속 괴롭히세요. 1~2레벨에는 무리하게 싸우기보다 평타와 스킬로 조금씩 체력을 깎는 것이 좋아요.', lv3: '오공이 (E)\'근두운 급습\'으로 빠르게 진입하면 (E)\'영웅의 비상\'을 사용해 지형을 타고 빠르게 빠져나가세요. (W)\'분신 전사\'로 투명해질 때는 오공의 실제 위치를 파악한 뒤 (Q)\'복수의 부메랑\'을 맞혀 이동 속도를 챙기세요. 오공의 진입기가 모두 빠진 타이밍에 짧게 딜교환을 하고 빠지는 것이 중요해요.', lv6: '(R)\'회전격\'에 맞으면 공중에 떠서 아무것도 못 하니 오공이 휘두르는 범위 밖으로 (E)\'영웅의 비상\'을 써서 피하세요. 오공의 체력이 낮아졌을 때 (R)\'인과응보\'를 충전해 발사하면 확실하게 처치할 수 있어요. 오공은 진입력이 좋으니 강가 쪽 시야를 확보하고 정글러의 개입에 대비하세요.', item: '크라켄 학살자를 첫 코어로 가서 세 번째 공격마다 추가 피해를 입히며 압박하세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'바위 피부\'의 체력 재생 효과를 억제하고 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 던지고 다시 불러들일 때 경로를 잘 피해서 피해를 줄여야 해요. (Q)\'복수의 부메랑\'을 사용해 멀리서 견제하며 오로라가 (P)\'영혼 방호술\'로 체력을 회복할 기회를 주지 마세요. 초반에는 무리하게 들어가기보다 거리 조절에 집중하며 안정적으로 파밍하세요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면 (E)\'영웅의 비상\'으로 빠르게 따라붙어 딜교환을 시도하세요. (W)\'장막 너머로\'를 사용하여 투명해진 오로라는 무리하게 쫓기보다 미니언을 챙기며 기다려야 해요. 오로라의 (Q)\'이중 저주\'가 빠진 타이밍에 (Q)\'복수의 부메랑\'을 맞춰서 압박하는 것이 좋아요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용해 영역을 만들면 그 안에서 싸우기보다 영역 밖에서 거리를 유지하며 대응하세요. 오로라의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용해 확실하게 킬을 노리는 것이 중요해요. 오로라가 (W)\'장막 너머로\'를 활용해 도망칠 수 있으니 정글러를 부를 때 위치를 잘 파악해 두세요.', item: '굶주린 히드라를 첫 코어로 올려서 라인 정리와 생명력 흡수를 챙기세요. 신발은 오로라의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하며 버티는 것을 막기 위해 점화가 필요해요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 초반 방어 스탯이 높으니 무리하게 붙지 마세요. (Q)\'용암 균열\'이 지나간 자리에 생기는 용암 기둥을 피해 거리 조절을 하세요. (Q)\'복수의 부메랑\'을 사용하여 멀리서 체력을 깎으며 파밍하세요.', lv3: '오른이 (E)\'화염 돌진\'으로 벽에 부딪혀 적을 띄우지 못하도록 벽 근처에서는 조심하세요. (W)\'불꽃 풀무질\'의 마지막 불꽃을 맞으면 불안정 상태가 되어 이동 불가 효과가 길어지니 오른의 정면을 피하세요. (E)\'영웅의 비상\'으로 빠르게 거리를 벌리거나 붙으며 딜교환을 하세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령이 다가올 때 진행 방향을 확인하고 띄워지지 않도록 주의하세요. 오른의 체력이 낮다면 (R)\'인과응보\'를 사용하여 킬을 노려보세요. 정령에 부딪혀 공중으로 띄워지면 스킬을 쓸 수 없으니 정글러가 올 때 위치 선정을 잘 하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 오른의 높은 체력을 공략하세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 탱커라 킬을 내기 어려우니 순간이동으로 라인 손해를 줄이세요.' },
    '올라프': { lv1: '(Q)\'복수의 부메랑\'을 던져서 최대한 멀리서 견제하며 올라프의 체력을 깎으세요. 올라프가 (Q)\'역류\'를 던져 방어력을 낮추고 둔화를 걸면 (E)\'영웅의 비상\'으로 거리를 벌리는 것이 좋아요. 1~2레벨에는 올라프의 맞딜이 강한 구간이니 무리하게 붙지 마세요.', lv3: '(W)\'버티기\'를 사용한 올라프는 보호막과 공격 속도가 올라가니 딜교환을 피하세요. (Q)\'복수의 부메랑\'을 맞춘 뒤 (E)\'영웅의 비상\'으로 거리를 조절하며 (P)\'비열한 싸움\'의 추가 피해를 챙기세요. 올라프의 (Q)\'역류\'가 빠진 타이밍에 짧게 교환하는 것이 안전해요.', lv6: '(R)\'라그나로크\'를 켠 올라프는 이동 방해 효과에 면역이 되니 정면 대결을 피하고 (E)\'영웅의 비상\'으로 거리를 두세요. 올라프의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 확실하게 마무리하세요. 정글러가 올 때는 (E)\'영웅의 비상\'을 활용해 지형을 넘어 빠르게 도망치세요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 판금 장화로 올라프의 기본 공격 피해를 줄이고 몰락한 왕의 검으로 전투력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 남은 체력을 빠르게 깎아 확실하게 처치하세요.' },
    '요네': { lv1: '요네가 (Q)\'필멸의 검\' 중첩을 쌓아 돌풍으로 띄우기 전에 (Q)\'복수의 부메랑\'으로 거리를 유지하며 견제하세요. (P)\'사냥꾼의 길\' 마법 피해가 섞이니 평타 맞교환은 짧게 가져가는 것이 좋아요. 요네의 돌진이 빠졌을 때 (Q)\'복수의 부메랑\'을 맞히며 압박하세요.', lv3: '요네가 (W)\'영혼 가르기\'를 사용해 보호막을 얻었을 때는 딜교환을 피하고 보호막이 사라진 뒤에 들어가세요. 요네가 (E)\'영혼해방\'으로 영혼 상태일 때는 육신이 있는 위치를 파악하며 거리를 조절하세요. (E)\'영웅의 비상\'을 사용하여 요네의 (Q)\'필멸의 검\' 돌진을 피하며 딜교환을 시도하세요.', lv6: '요네가 (R)\'운명봉인\'을 사용해 적을 끌어당기며 공중으로 띄울 수 있으니 일직선으로 뭉쳐 있지 마세요. 요네의 체력이 낮아진 것을 확인했다면 (R)\'인과응보\'를 사용해 확실하게 처치하세요. 요네의 궁극기 연계가 강한 구간이니 정글러가 근처에 있다면 라인을 당겨 두는 것이 좋아요.', item: '첫 코어로 몰락한 왕의 검을 가서 요네와의 맞대결 능력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 요네가 (W)\'영혼 가르기\' 보호막을 사용한 뒤에 점화로 마무리 피해를 더하기 좋아요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 처치해 무덤을 쌓으려 하니 (Q)\'복수의 부메랑\'으로 계속 견제하며 방해하세요. (P)\'영혼의 길잡이\'로 소환된 망령들이 다가오면 거리 조절을 통해 피해를 최소화하고 짧은 딜교환만 시도하세요. 무덤이 적은 상태의 요릭을 상대로는 원거리 공격을 통해 일방적으로 체력을 깎는 것이 좋아요.', lv3: '요릭이 (E)\'애도의 안개\'를 던져 방어력을 깎고 둔화를 걸면 망령들이 빠르게 달려드니 투사체 방향을 보고 피하세요. (W)\'망자의 진\' 벽은 공격을 받으면 파괴되니 막혔을 때는 당황하지 말고 벽을 부수거나 돌아가세요. (Q)\'복수의 부메랑\'을 맞춰 이동 속도를 얻은 뒤 요릭의 스킬이 빠진 타이밍에 짧게 진입해 공격하고 빠지세요.', lv6: '(R)\'군도의 장송곡\'으로 소환된 안개 마녀와 망령들이 함께 공격하면 피해가 매우 크니 요릭과 정면으로 오래 싸우지 마세요. 요릭의 체력이 어느 정도 깎였을 때 (R)\'인과응보\'를 충전해 발사하면 잃은 체력에 비례한 피해로 빠르게 처치할 수 있어요. 마녀가 라인을 밀어붙일 때는 (E)\'영웅의 비상\'을 이용해 빠르게 합류하거나 정글러를 불러 함께 대응하세요.', item: '판금 장화로 요릭과 망령들의 기본 공격 피해를 줄이세요. 삼위일체는 공격 속도와 체력을 제공해 요릭과의 지속적인 교전에서 버티며 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 체력을 회복하며 끈질기게 버티는 것을 방해하고, 낮은 체력에서 확실하게 마무리하기 위해 점화가 필요해요.' },
    '우디르': { lv1: '(Q)\'복수의 부메랑\'을 던져 우디르가 접근하기 전에 체력을 깎아두세요. 우디르가 (Q)\'야생 발톱\'을 켜고 다가오면 맞대결하기보다 거리를 벌리는 것이 안전해요. (E)\'불길 쇄도\'로 달려드는 타이밍에 맞춰 (E)\'영웅의 비상\'을 쓰기보다 거리 조절에 집중하세요.', lv3: '우디르가 (W)\'강철 갑옷\'으로 보호막을 얻었을 때는 무리하게 딜교환을 하지 마세요. 우디르의 (E)\'불길 쇄도\' 기절이 빠진 것을 확인한 뒤에 (Q)\'복수의 부메랑\'을 맞히며 압박하세요. (E)\'영웅의 비상\'으로 지형을 이용해 우디르의 공격 사거리에서 빠르게 벗어나는 것이 중요해요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 사용해 둔화를 걸며 다가오면 (R)\'인과응보\'를 저장하며 대응하세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되는 순간에는 (E)\'영웅의 비상\'으로 거리를 벌리며 기다리세요. 우디르의 체력이 낮아지면 (R)\'인과응보\'를 발사해 확실하게 킬을 노리세요.', item: '첫 코어로 몰락한 왕의 검을 선택해 우디르와 근접전에서 싸우세요. 신발은 우디르의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복할 때 점화를 사용해 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 압박하고 평타에 (P)\'화염의 메아리\'가 묻어 있어 근접 교전이 위험해요. (Q)\'부식성 폭약\'이 날아오는 위치를 잘 피하며 (Q)\'복수의 부메랑\'으로 원거리 견제를 해주세요. 첫 웨이브에서는 무리하게 딜교환하기보다 거리 조절을 하며 막타를 챙기는 것이 중요해요.', lv3: '우르곳이 (E)\'경멸\'로 돌진해 나를 뒤로 던지면 기절하므로 돌진 경로에서 빠르게 벗어나세요. (Q)\'부식성 폭약\'에 맞으면 (W)\'심판의 원\'의 우선 공격 대상이 되니 둔화 상태에서는 거리 조절을 철저히 해야 해요. 우르곳의 (E)\'경멸\'이 빠진 타이밍에 (E)\'영웅의 비상\'으로 빠르게 진입했다가 빠지며 딜교환을 시도하세요.', lv6: '(R)\'불사의 공포\' 섬광탄이 꽂힌 채 체력이 낮아지면 제압당해 처형될 수 있으니 즉시 거리를 벌리세요. 우르곳의 체력이 낮을 때 (R)\'인과응보\'를 사용해 먼저 처치하면 위험한 상황을 방지할 수 있어요. (E)\'영웅의 비상\'은 챔피언이나 지형에 부딪히면 일찍 끝나니 진입 경로를 미리 확인하세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 우르곳에게 지속 피해를 입히세요. 신발은 우르곳의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우르곳의 높은 체력을 깎아 (R)\'인과응보\'로 마무리하기 위해 점화의 추가 피해가 필요해요.' },
    '워윅': { lv1: '(Q)\'복수의 부메랑\'으로 계속 체력을 깎으며 거리를 유지하세요. 워윅의 (Q)\'야수의 송곳니\'는 대상을 지정하는 도약이라 미니언 뒤에 숨어도 맞으니, 체력이 낮다면 최대한 붙지 않도록 주의하세요. (P)\'비열한 싸움\'의 보호막을 활용해 짧은 딜교환 후 빠르게 빠져나와야 해요.', lv3: '워윅이 (E)\'원시의 포효\'를 켜면 받는 피해가 줄어드니 포효가 끝날 때까지 기다리세요. (W)\'피의 사냥\'으로 인해 내 체력이 낮을 때 워윅의 이동 속도가 매우 빨라지니 체력 관리에 신경 써야 해요. (E)\'영웅의 비상\'은 워윅의 공포 범위를 벗어나거나 빠르게 위치를 잡는 용도로 사용하세요.', lv6: '(R)\'무한의 구속\'은 제압 스킬이라 맞으면 정화로도 풀 수 없고 아무것도 못 하니 직선 거리에서 비켜나세요. 워윅의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하면 잃은 체력 비례 피해로 회복량을 뚫고 마무리할 수 있어요. 라인을 적절히 당겨서 상대 정글러와 워윅의 연계 제압에 당하지 않게 하세요.', item: '몰락한 왕의 검과 판금 장화를 추천해요. 판금 장화는 워윅의 기본 공격 피해를 줄여주고 몰락한 왕의 검은 강력한 피해를 입혀요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\'의 체력 회복 효과를 억제해야 킬각을 잡기 편해요.' },
    '이렐리아': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 활용해 멀리서 이렐리아의 체력을 깎으며 거리를 유지하세요. 이렐리아가 미니언을 타고 (Q)\'칼날 쇄도\'로 빠르게 접근하지 못하도록 미니언과의 거리를 조절하는 것이 중요해요. (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 짧게 치고 빠지며 압박하세요.', lv3: '이렐리아의 (E)\'쌍검협무\'가 날아오는 궤적을 보고 옆으로 움직여 기절과 표식을 피해야 해요. 이렐리아가 (W)\'저항의 춤\'을 사용하여 받는 피해를 줄이고 있다면 무리하게 공격하지 말고 기다리세요. (E)\'영웅의 비상\'을 사용하여 이렐리아의 돌진 경로를 예측하며 위치를 잡고 (Q)\'복수의 부메랑\'으로 딜교환을 시도하세요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 사용하여 결계를 만들면 그 안에서 둔화되지 않도록 빠르게 위치를 옮기세요. 상대의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 잃은 체력 비례 피해로 확실하게 처치하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오는 타이밍에는 (E)\'영웅의 비상\'을 사용하여 도주 경로를 확보하며 대응하세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 이렐리아와의 근접 교전 능력을 높이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. 이렐리아의 (E)\'쌍검협무\'로 인한 기절을 빠르게 풀고 대응할 수 있어요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에 촉수를 소환해 공격하니 지형에서 멀리 떨어져 라인 중앙을 잡으세요. (Q)\'복수의 부메랑\'으로 견제하며 일라오이가 (Q)\'촉수 강타\'를 사용할 때 거리 조절을 통해 피해를 최소화하세요. 1~2레벨에는 무리하게 딜교환을 하기보다 원거리 공격으로 체력을 깎는 데 집중하세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼이 받은 피해 일부가 나에게 전이되고 영혼에서 너무 멀어지면 숙주가 되어 촉수를 소환하니 주의하세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약해 붙으려 하면 (E)\'영웅의 비상\'으로 지형을 타고 빠르게 빠져나오세요. (Q)\'복수의 부메랑\'을 계속 맞혀 이동 속도를 얻으며 일라오이의 스킬 사거리 밖에서 짧은 딜교환을 반복하세요.', lv6: '(R)\'믿음의 도약\'을 사용하면 주변에 촉수가 많이 소환되어 근접전이 매우 위험하니 즉시 거리를 벌리세요. 일라오이의 체력이 낮아졌을 때 (R)\'인과응보\'를 충전해 발사하면 잃은 체력에 비례한 피해로 마무리할 수 있어요. 라인을 당겨 정글러를 부르고 일라오이가 벽에서 떨어진 곳으로 나오도록 유도하세요.', item: '크라켄 학살자를 가서 추가 피해를 입히며 체력이 높은 일라오이를 압박하세요. 신발은 일라오이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 복귀 시간을 줄이고 점멸로 (E)\'영혼의 시험\' 같은 위험한 스킬을 빠르게 피하세요.' },
    '자크': { lv1: '1~2레벨 구간에서는 (Q)\'복수의 부메랑\'을 활용해 자크가 다가오기 전에 꾸준히 견제하세요. 자크가 (Q)\'탄성 주먹\'으로 접근하려 하면 옆으로 무빙하며 거리를 유지하고, 자크가 (P)\'세포 분열\' 조각을 흡수하며 회복하지 못하도록 압박하세요.', lv3: '자크가 (E)\'새총 발사\'로 돌진할 준비를 하면 (E)\'영웅의 비상\'을 사용해 지형으로 빠르게 이동하며 피하세요. 자크가 (W)\'불안정 물질\'을 사용해 주변에 피해를 주려 할 때는 적절히 거리를 벌려 피해를 최소화하세요. 자크의 (Q)\'탄성 주먹\'이 빠진 타이밍에 (Q)\'복수의 부메랑\'과 평타로 딜교환을 시도하세요.', lv6: '자크가 (R)\'바운스!\'로 튀어 올라 공중에 띄우려 하면 (E)\'영웅의 비상\'으로 위치를 선점해 대응하세요. 자크의 체력이 낮아지면 (R)\'인과응보\'를 사용해 잃은 체력 비례 피해로 빠르게 처치해야 해요. 자크는 (P)\'세포 분열\'로 쓰러져도 조각이 모여 부활할 수 있으니, 처치한 뒤에도 조각을 공격해 부활을 막으세요.', item: '자크의 높은 체력을 깎기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 자크의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 (P)\'세포 분열\'을 통해 체력을 회복하는 것을 억제하세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'를 사용해 두 번 공격하며 체력을 회복하므로 1~2레벨에는 맞대결을 피하세요. (Q)\'복수의 부메랑\'을 던져 멀리서 자헨의 체력을 깎으며 거리를 유지하세요. 자헨이 (Q)\'다르킨의 글레이브\' 효과를 가진 평타를 치러 오면 뒤로 물러나며 미니언을 챙겨요.', lv3: '자헨이 (W)\'공포의 귀환\'을 사용하여 끌어당기려 하면 직선에서 벗어나세요. (E)\'찬란한 쇄도\'로 돌진해 들어오는 자헨에게 (E)\'영웅의 비상\'을 사용하여 위치를 잡으세요. (P)\'전쟁 단련\' 중첩을 자헨에게 쌓아주지 않도록 짧게 교환하고 빠져요.', lv6: '자헨이 (R)\'단호한 판결\'로 내려찍으며 체력을 회복하려 하면 낙하 지점을 미리 확인하고 피하세요. 자헨의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 확실하게 마무리하세요. (P)\'전쟁 단련\'이 가득 차서 자헨이 부활할 수 있으니 방심하지 말고 주의하세요.', item: '첫 코어로 몰락한 왕의 검을 가서 자헨과의 전투 지속력을 높이세요. 신발은 자헨의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하므로 점화의 치유 감소 효과가 필요해요.' },
    '잭스': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 활용해 최대한 멀리서 잭스의 체력을 깎으며 거리를 유지하세요. 잭스가 (Q)\'도약 공격\'으로 들어오며 (P)\'가차없는 맹공\'의 공격 속도를 쌓기 전에 빠르게 물러나는 것이 중요해요. (P)\'비열한 싸움\'의 보호막을 얻기 위해 챔피언을 타격하며 안정적으로 라인을 관리하세요.', lv3: '잭스가 (E)\'반격\'을 켜면 기본 공격을 모두 피하니 (P)\'비열한 싸움\'의 평타를 낭비하지 마세요. 잭스의 (W)\'무기 강화\' 평타를 맞지 않도록 (E)\'영웅의 비상\'을 사용해 지형으로 빠르게 거리를 벌리세요. (E)\'반격\'이 끝나며 주변을 기절시키니 지속 중에는 가까이 붙지 말고 끝난 직후에 다시 스킬을 맞춰 딜교환을 시도하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 켜서 방어력과 마법 저항력을 높인 동안에는 정면 승부를 피하고 거리를 유지하세요. 잭스의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 사용하여 확실하게 처치할 기회를 잡으세요. (E)\'영웅의 비상\'을 활용해 벽을 타고 이동하며 잭스의 (Q)\'도약 공격\' 사거리 밖에서 라인 주도권을 유지하세요.', item: '징수의 총을 코어 아이템으로 선택해 낮은 체력의 잭스를 확실히 마무리하세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 잭스의 체력을 깎아 (R)\'인과응보\'의 처치 기회를 높이세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 사용하며 멀리서 견제하므로 (Q)\'복수의 부메랑\'을 활용해 함께 압박하세요. 제이스가 해머 형태로 바꿔 (Q)\'하늘로!\'를 쓰며 접근하면 무리하게 맞서지 말고 거리를 유지하세요. 초반에는 제이스의 견제를 받아내며 체력을 관리하는 것이 중요해요.', lv3: '제이스가 해머 (E)\'천둥 강타\'를 사용하여 뒤로 밀쳐낼 수 있으니 거리를 조절하며 (E)\'영웅의 비상\'으로 접근하세요. 제이스가 캐논 형태로 (Q)\'전격 폭발\'을 쏠 때 부메랑을 맞춰 반격을 시도하세요. 제이스의 해머 (E)\'천둥 강타\'를 피한 뒤에 빠르게 붙으면 딜교환을 주도할 수 있어요.', lv6: '제이스의 체력이 낮아진 상태라면 (R)\'인과응보\'를 사용하여 확실하게 킬을 노리세요. 제이스가 (R)\'머큐리 캐논\'으로 변환하여 멀리서 공격할 수 있으니 무작정 접근하기보다 체력 상황을 살피세요. 제이스가 해머로 변환하여 (E)\'천둥 강타\'로 밀어내려 할 때 (E)\'영웅의 비상\'으로 지형을 이용해 대응하세요.', item: '굶주린 히드라를 첫 코어로 선택하여 생명력 흡수로 전투 지속력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄이기 위해 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 제이스가 (E)\'천둥 강타\'로 밀어내려고 할 때 점멸을 사용해 거리를 좁히고 점화로 마무리하세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 적을 공중에 띄우고 둔화를 주니 바닥의 표시를 보고 피해야 해요. (E)\'날카로운 가시\'는 정면의 적을 둔화시키므로 초가스의 정면을 피해서 (Q)\'복수의 부메랑\'으로 멀리서 견제하세요. 1~2레벨에는 초가스가 미니언을 먹으며 (P)\'육식\'으로 체력을 회복하지 못하게 평타를 섞어주세요.', lv3: '초가스의 (W)\'흉포한 울부짖음\'을 맞으면 스킬을 쓸 수 없으니 원뿔 범위 밖에서 대기하세요. 초가스가 (W)\'흉포한 울부짖음\'을 허공에 사용했다면 (E)\'영웅의 비상\'으로 빠르게 접근해 딜교환을 시도하세요. (Q)\'복수의 부메랑\'을 맞히면 이동 속도가 증가하니 이를 활용해 거리를 조절하며 싸우세요.', lv6: '초가스의 (R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 주므로 체력이 낮을 때는 거리를 유지하세요. 초가스의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 사용하면 잃은 체력에 비례한 피해로 킬을 노려보세요. 라인을 밀어넣고 초가스가 (R)\'포식\'으로 큰 성장을 하지 못하도록 압박하는 것이 중요해요.', item: '헤르메스의 발걸음을 선택해 초가스의 마법 피해와 침묵 지속 시간을 줄이세요. 첫 코어 아이템으로는 초가스의 높은 체력을 상대하기 좋은 몰락한 왕의 검을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\' 회복량을 줄이며 전투를 마무리하세요.' },
    '카밀': { lv1: '(Q)\'복수의 부메랑\'을 활용해 멀리서 카밀의 체력을 깎으며 거리를 유지하세요. 카밀은 챔피언에게 기본 공격하면 (P)\'적응형 방어 체계\' 보호막이 생기니 짧게 교환하고 빠져서 보호막을 얻을 기회를 줄이세요. 카밀이 (Q)\'정확성 프로토콜\'을 사용해 다가오면 뒤로 물러나서 강화 공격을 피하는 것이 중요해요.', lv3: '카밀의 (W)\'전술적 휩쓸기\'는 원뿔 바깥쪽에 맞으면 둔화와 추가 피해가 들어가고 카밀이 체력을 회복하니 바깥쪽 거리를 피하세요. 카밀이 (E)\'갈고리 발사\'를 사용하여 도약하며 기절을 시도할 때 (E)\'영웅의 비상\'으로 빠르게 거리를 벌리거나 위치를 옮겨 대응하세요. 카밀의 (Q)\'정확성 프로토콜\' 재사용 대기시간을 확인하며 (Q)\'복수의 부메랑\'으로 견제하는 구도를 만드세요.', lv6: '카밀의 (R)\'마법공학 최후통첩\' 범위 안에 갇히면 어떤 방법으로도 탈출할 수 없으니 구역 안에서 무리하게 싸우지 마세요. 카밀의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 확실하게 처치하고 킬을 가져가세요. 카밀이 (E)\'갈고리 발사\'를 이용해 벽을 타고 진입할 수 있으니 벽 근처에서는 항상 주의하며 라인을 관리하세요.', item: '몰락한 왕의 검을 첫 코어로 선택하여 카밀과의 맞대결에서 생명력 흡수와 공격력을 확보하세요. 신발은 카밀의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제할 수 있어요.' },
    '카사딘': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'을 던져 거리를 유지하며 견제해요. 카사딘이 (Q)\'무의 구체\'로 보호막을 얻으며 다가오는 것을 조심하면서 안정적으로 파밍에 집중하세요.', lv3: '3레벨 이후에는 (Q)\'복수의 부메랑\'을 맞춘 뒤 평타를 섞어 (P)\'비열한 싸움\' 피해를 입혀요. 카사딘의 (E)\'힘의 파동\'을 맞지 않도록 거리 조절을 철저히 하며 딜교환을 진행하세요.', lv6: '6레벨이 되면 카사딘의 (R)\'균열 이동\'을 사용한 진입을 조심하며 라인 관리에 집중해요. 적의 체력이 낮아진 타이밍에 (R)\'인과응보\'를 사용하여 확실하게 킬을 노려보세요.', item: '헤르메스의 발걸음과 굶주린 히드라를 선택해요. 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신고 생명력 흡수를 위해 굶주린 히드라를 구매해요.', spell: '점멸과 점화. 점화는 적의 체력을 낮춰 킬을 따기 쉽게 도와주고 점멸은 위치 선정에 도움을 줘요.' },
    '카시오페아': { lv1: '(Q)\'복수의 부메랑\'으로 견제하면서 상대의 (Q)\'맹독 폭발\'에 맞지 않도록 계속 움직여주세요. 무리한 진입보다는 부메랑 적중 시 얻는 이동 속도를 활용해 적절한 거리를 유지하며 체력을 깎으세요.', lv3: '(E)\'영웅의 비상\'을 쓰기 전 상대의 (W)\'독기의 늪\'이 빠졌는지 확인하세요. 늪에 닿으면 이동 스킬을 사용할 수 없으니 주의하고, (E)\'쌍독니\'의 추가 피해를 피하기 위해 중독된 상태에서는 빠르게 거리를 벌리세요.', lv6: '(R)\'인과응보\'를 사용하여 상대의 잃은 체력에 비례한 피해로 확실하게 마무리하세요. (R)\'석화의 응시\'가 발사될 때 카시오페아를 등지면 기절하지 않고 둔화만 적용되니 빠르게 방향을 틀어야 해요.', item: '헤르메스의 발걸음과 마법사의 최후를 추천해요. 마법 저항력과 강인함을 높여 기절과 둔화 시간을 줄이고 공격 속도로 빠르게 피해를 입히기 위해서예요.', spell: '점멸과 정화예요. 정화로 (R)\'석화의 응시\'의 기절 효과를 즉시 풀어내고 생존 확률을 높이기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 날려 (P)\'폭풍의 표식\'을 쌓으며 견제해요. (Q)\'복수의 부메랑\'을 사용하여 거리 조절을 하며 같이 견제하고, 수리검이 날아오는 궤적을 피해 옆으로 움직이세요. 표식이 많이 쌓였다면 기절이 곧 오니 잠시 뒤로 물러나 안전하게 받아내세요.', lv3: '(E)\'번개 질주\'로 빠르게 다가와 표식을 남기려는 케넨의 움직임을 잘 읽으세요. 표식이 쌓인 상태에서 (W)\'전류 방출\'을 맞으면 기절하므로, (E)\'영웅의 비상\'으로 지형에 매달려 공격하며 거리 조절을 하세요. 케넨의 돌진기가 빠진 시점에 짧게 평타 교환을 시도하고 빠르게 빠져나와야 해요.', lv6: '(R)\'날카로운 소용돌이\'가 켜진 케넨 주변에 오래 머물면 순식간에 기절하므로 즉시 거리를 벌리세요. 소용돌이가 끝난 뒤 체력이 낮아진 케넨에게 (R)\'인과응보\'를 충전해 발사하면 안전하게 마무리할 수 있어요. 정글러가 올 때 (E)\'영웅의 비상\'으로 빠르게 합류하거나 퇴로를 확보해 기절 연계를 피하세요.', item: '마법사의 최후를 첫 코어로 가서 마법 저항력과 공격 속도를 챙겨 케넨의 피해를 견디세요. 신발은 마법 저항력을 높이고 기절 지속 시간을 줄이는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 체력이 낮은 케넨을 확실하게 마무리하여 킬을 가져오기 좋아요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 성장하기 전인 1~2레벨 구간에 매우 약해요. (Q)\'복수의 부메랑\'을 던져서 케일의 체력을 깎으며 압박하세요. 케일의 (Q)\'광휘의 일격\'에 맞아 방어력과 마법 저항력이 감소하지 않도록 주의하며 거리 조절을 하세요.', lv3: '(E)\'영웅의 비상\'을 사용하여 케일에게 접근해 (P)\'비열한 싸움\'의 보호막을 활용하며 싸우세요. 케일이 (E)\'화염주문검\'을 사용하면 잃은 체력에 비례한 큰 피해를 입으니 주의해야 해요. 케일의 (Q)\'광휘의 일격\'을 먼저 피한 뒤에 (Q)\'복수의 부메랑\'을 맞춰 딜교환을 시작하세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용하여 무적이 되면 (R)\'인과응보\'의 피해가 들어가지 않아요. 무적 상태가 끝나는 것을 확인한 뒤에 (R)\'인과응보\'를 사용해서 킬을 노려야 해요. 케일의 성장을 늦추기 위해 라인을 계속 압박하며 정글의 도움을 요청하세요.', item: '징수의 총을 첫 코어로 가서 초반에 빠르게 킬을 가져오세요. 신발은 케일의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 케일의 (W)\'천상의 축복\' 회복량을 줄이며 킬을 노리세요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'을 사용하여 방어력과 마법 저항력을 낮추는 구간을 조심하며 거리를 유지하세요. (Q)\'복수의 부메랑\'을 활용하여 파밍을 돕고 상대의 체력을 조금씩 깎아두는 것이 좋아요. 초반에는 무리하게 교전하기보다 미니언을 챙기며 성장에 집중해요.', lv3: '코그모가 (W)\'생체마법 폭격\'을 켜고 거리를 벌린다면 (E)\'영웅의 비상\'을 사용해 빠르게 접근하세요. 코그모가 깔아두는 (E)\'공허의 분비물\' 둔화 지역을 피하며 진입하는 것이 중요해요. 접근에 성공하면 (P)\'비열한 싸움\' 스택을 쌓으며 강력하게 압박하세요.', lv6: '코그모의 체력이 낮아진 것을 확인하면 (R)\'인과응보\'를 사용하여 확실하게 마무리하세요. 상대가 (R)\'살아있는 곡사포\'로 위치를 드러내고 멀리서 공격할 수 있으니 주의해야 해요. (E)\'영웅의 비상\'으로 적의 공격을 피하며 정글러와 함께 적극적으로 움직이세요.', item: '헤르메스의 발걸음과 삼위일체를 가요. 코그모의 마법 피해를 견디고 전투력을 높이기 위해서예요.', spell: '점멸과 점화. (R)\'인과응보\'의 피해를 극대화하고 코그모를 빠르게 처치하기 위해서예요.' },
    '코르키': { lv1: '(Q)\'인광탄\'의 견제를 피하며 미니언을 챙기세요. (Q)\'복수의 부메랑\'을 맞혀 이동 속도를 얻으며 코르키의 사거리 밖으로 빠르게 빠지거나 기회를 엿보세요.', lv3: '코르키가 (E)\'개틀링 건\'을 사용할 때 정면에서 벗어나 방어력 감소 효과를 피하세요. (E)\'영웅의 비상\'으로 빠르게 접근한 뒤 기본 공격과 스킬을 섞어 짧게 딜교환하고 빠지세요.', lv6: '코르키의 (R)\'미사일 폭격\' 세 번째 탄환을 피한 뒤 체력이 낮아진 틈을 타 (R)\'인과응보\'로 마무리하세요. (E)\'영웅의 비상\'을 통해 지형을 활용하며 정글러의 개입을 유도하는 것이 좋아요.', item: '헤르메스의 발걸음과 마법사의 최후를 추천해요. 마법 저항력을 높여 상대의 마법 피해를 줄이고 공격 속도를 확보해 지속 딜교환을 하세요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고 점멸로 (E)\'영웅의 비상\' 각을 만드세요.' },
    '퀸': { lv1: '1~2레벨에는 퀸이 (P)\'매사냥\' 표식이 붙은 대상에게 첫 평타를 강하게 때리니 거리를 유지하며 파밍하세요. (Q)\'복수의 부메랑\'을 사용하여 퀸의 체력을 깎으며 압박하고, 표식이 붙어 있을 때는 교환을 짧게 끊으며 (P)\'비열한 싸움\' 스택을 쌓으세요.', lv3: '3레벨에는 퀸이 (E)\'공중제비\'를 사용하여 돌진하고 둔화를 걸려고 할 때 (E)\'영웅의 비상\'을 사용해 위치를 잡거나 거리를 벌리세요. 퀸의 (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 주의하고, 퀸의 돌진이 빠진 직후에 (Q)\'복수의 부메랑\'을 맞히며 딜교환을 시도하세요.', lv6: '6레벨 이후 퀸이 (R)\'후방 지원\'으로 빠르게 이동하며 합류를 시도하면 라인을 관리하며 퀸의 움직임을 주시하세요. 퀸의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 킬을 노리고, (E)\'영웅의 비상\'으로 지형을 활용해 퀸의 접근을 방어하세요.', item: '징수의 총을 첫 코어로 가서 킬 결정력을 높이세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 퀸의 체력이 낮아졌을 때 점화로 확실하게 마무리할 수 있어요.' },
    '크산테': { lv1: '(Q)\'복수의 부메랑\'으로 끊임없이 견제하며 체력을 깎으세요. 크산테가 (Q)\'엔토포 타격\'을 한 번 맞혔을 때 바로 거리를 벌려 두 번째 중첩의 기절과 끌어당기기를 피하는 것이 중요해요. 첫 웨이브부터 거리 조절을 하며 상대가 다가오지 못하게 압박하세요.', lv3: '크산테가 (W)\'길을 여는 자\'를 충전하며 다가올 때 (E)\'영웅의 비상\'으로 지형에 매달려 돌진 경로에서 벗어나세요. (E)\'발놀림\'으로 보호막을 얻으며 진입하는 타이밍을 피한 뒤, 상대의 주요 CC기가 빠진 틈에 평타와 스킬을 섞어 짧게 딜교환해요. (W)\'길을 여는 자\'의 기절을 맞지 않도록 항상 주의하세요.', lv6: '(R)\'총공세\'를 사용한 크산테는 피해량과 체력 회복량이 늘어나니 정면에서 맞서지 말고 거리를 두세요. 상대의 체력이 낮아졌을 때 (R)\'인과응보\'를 충전해 발사하여 마무리하세요. 벽 근처에 있으면 (R)\'총공세\'에 밀려 벽을 뚫고 날아갈 수 있으니 라인 중앙에서 교전하고 정글러의 개입을 기다리세요.', item: '체력이 많은 크산테를 상대하기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 상태의 크산테가 가진 모든 피해 흡혈로 회복하는 것을 방해하고 마무리 피해를 높이기 위해서예요.' },
    '클레드': { lv1: '클레드가 스칼을 타고 있을 때는 피해를 스칼이 대신 받으므로 (Q)\'복수의 부메랑\'을 계속 던져 스칼의 체력을 깎아두세요. (Q)\'덫날리기\'에 맞았을 때 클레드와 근거리를 유지하면 끌려가며 큰 피해를 입으니 즉시 거리 조절을 하며 벗어나세요.', lv3: '클레드가 (W)\'버럭버럭\'을 켜고 빠르게 공격할 때는 평타 교전을 피하고 (E)\'영웅의 비상\'으로 지형을 타고 빠르게 위치를 옮기세요. (E)\'이랴!\'로 다시 돌진하는 타이밍에 맞춰 (Q)\'복수의 부메랑\'을 던져 피해를 입히고 거리 조절을 하는 것이 중요해요.', lv6: '스칼은 (R)\'돌겨어어억!!!\' 경로상의 첫 번째 적 챔피언에게 돌격하니 돌진 경로에서 미리 벗어나세요. 스칼에서 내린 클레드는 챔피언 피해량이 줄어드니 이때 (E)\'영웅의 비상\'으로 압박하고, 체력이 낮아지면 (R)\'인과응보\'로 빠르게 처치하세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 클레드의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력을 동시에 챙겨 지속 싸움에 도움을 줘요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드의 체력을 점화로 빠르게 깎아 (R)\'인과응보\'로 마무리하기 좋아요.' },
    '탐켄치': { lv1: '탐 켄치가 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으려 하니 미니언 뒤에 서서 첫 번째 대상이 되지 않도록 주의하세요. (Q)\'복수의 부메랑\'을 사용하여 거리를 유지하며 탐 켄치의 체력을 깎으세요. (P)\'절대 미각\' 중첩이 쌓이면 기절할 수 있으니 교환을 짧게 하고 빠져야 해요.', lv3: '탐 켄치의 (Q)\'혀 채찍\'이 빠진 직후에 (Q)\'복수의 부메랑\'과 (E)\'영웅의 비상\'을 활용해 딜교환을 하세요. (W)\'심연 잠수\'로 공중에 띄우려 하면 범위를 벗어나서 피해를 피해야 해요. (E)\'두꺼운 피부\' 보호막이 켜져 있을 때는 딜을 아끼고 보호막이 사라진 뒤에 공격을 이어가세요.', lv6: '(P)\'절대 미각\' 중첩이 쌓인 상태에서 탐 켄치의 (R)\'집어삼키기\'에 먹히면 매우 위험하니 거리를 조절하세요. 탐 켄치의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 적을 마무리하세요. 탐 켄치가 (E)\'두꺼운 피부\'를 켜고 라인을 밀며 정글에 개입하려 하면 빠르게 웨이브를 정리하세요.', item: '탐 켄치의 높은 체력을 상대하기 위해 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 (Q)\'혀 채찍\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화를 사용하여 탐 켄치가 (Q)\'혀 채찍\'으로 체력을 회복하는 것을 억제하세요.' },
    '트런들': { lv1: '트런들이 (Q)\'깨물기\'로 공격력을 흡수하며 둔화를 걸기 때문에 1~2레벨에는 평타 교환을 피하세요. (Q)\'복수의 부메랑\'으로 멀리서 견제하며 트런들의 접근을 막는 것이 좋아요. 트런들은 (P)\'헌납\'으로 주변 유닛이 쓰러질 때 체력을 회복하니 미니언이 많은 곳에서는 싸우지 마세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 그 영역 안에서 회복량과 이동 속도가 늘어나니 영역 밖에서 교환하세요. (E)\'얼음 기둥\'은 지나갈 수 없는 기둥이라 길을 막고 주변을 둔화시키니 (E)\'영웅의 비상\'으로 진입할 때 기둥의 위치를 확인해야 해요. (Q)\'깨물기\'가 빠진 것을 확인한 뒤 (Q)\'복수의 부메랑\'을 맞히고 (E)\'영웅의 비상\'으로 붙으세요.', lv6: '트런들이 (R)\'진압\'을 사용하면 체력과 방어력을 뺏기니 사용 직후에는 정면 대결을 피하고 거리를 벌리세요. 트런들의 체력이 낮아지면 (R)\'인과응보\'를 사용하여 마무리하는 것이 효과적이에요. 트런들은 (P)\'헌납\'으로 체력을 회복하며 버티기 쉬우니 라인을 밀어 넣고 압박하는 것이 좋아요.', item: '트런들의 높은 체력을 상대하기 위해 몰락한 왕의 검을 첫 코어로 가세요. 신발은 트런들의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 트런들의 (P)\'헌납\'과 (W)\'얼음 왕국\'을 통한 체력 회복을 억제하세요.' },
    '트린다미어': { lv1: '(Q)\'복수의 부메랑\'을 던져서 멀리서 트린다미어의 체력을 깎으며 거리를 유지하세요. 트린다미어가 (Q)\'피의 갈망\'을 사용하여 체력을 회복하려 하면 (P)\'비열한 싸움\'의 보호막을 활용해 짧은 교환을 시도하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 거리를 좁혀오면 (E)\'영웅의 비상\'을 사용해 벽으로 빠르게 도망치거나 위치를 잡으세요. 만약 (W)\'조롱의 외침\'에 맞아 이동 속도가 느려진다면 (Q)\'복수의 부메랑\'을 챔피언에게 맞춰 이동 속도 증가 효과를 받아야 해요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 사용하여 죽지 않는 상태가 되면 무리하게 딜을 쏟지 말고 잠시 뒤로 물러나세요. (R)\'불사의 분노\'가 끝난 직후 체력이 낮은 트린다미어에게 (R)\'인과응보\'를 사용해 확실하게 마무리하세요.', item: '판금 장화와 몰락한 왕의 검을 추천해요. 판금 장화는 트린다미어의 기본 공격 피해를 줄여주고 몰락한 왕의 검은 생명력 흡수를 통해 라인 유지력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 억제하는 데 효과적이에요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 지속 피해를 입히고 (Q)\'실명 다트\'로 공격이 빗나가게 만들며 괴롭혀요. (P)\'유격 전투\'로 수풀에서 투명해질 수 있으니 수풀 근처에서는 항상 시야를 확인하며 움직이세요. (Q)\'복수의 부메랑\'을 맞춰 이동 속도를 얻으며 티모의 공격 사거리 밖에서 미니언을 챙기세요.', lv3: '(Q)\'실명 다트\'는 대상 지정이라 걸어서 피할 수 없으니, 실명된 동안에는 평타 대신 (Q)\'복수의 부메랑\'과 (E)\'영웅의 비상\'으로 피해를 넣거나 빠져나오세요. 티모가 (W)\'신속한 이동\'을 사용해 도망가려고 하면 (Q)\'복수의 부메랑\'을 맞춰 이동 속도를 얻어 추격하세요. (P)\'비열한 싸움\'의 보호막을 활용해 티모의 독 피해를 견디며 짧게 딜교환을 시도해요.', lv6: '티모가 설치한 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 주니 길목에 깔린 버섯을 미리 확인하며 이동하세요. 티모의 체력이 낮아졌을 때 (R)\'인과응보\'를 사용하여 잃은 체력 비례 피해로 확실하게 마무리하세요. 티모가 (P)\'유격 전투\'를 이용해 수풀로 숨어 기습할 수 있으니 라인 관리와 함께 정글러의 위치를 확인해요.', item: '헤르메스의 발걸음을 선택해 티모의 마법 피해와 군중 제어 지속 시간을 줄이세요. 굶주린 히드라를 첫 코어로 올려서 체력 회복과 라인 정리 능력을 보강하세요.', spell: '점멸과 점화를 추천해요. 티모의 체력이 낮아졌을 때 점화로 마무리 피해를 입히며 (R)\'인과응보\'로 처치하기 좋아요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 사용하여 멀리서 견제하며 1~2레벨에 강한 압박을 가해요. (Q)\'복수의 부메랑\'으로 거리를 유지하며 견제하고 판테온의 (P)\'필멸자의 의지\'가 쌓여 강화 스킬이 나가기 전에는 교환을 피하세요.', lv3: '판테온이 (W)\'방호의 도약\'으로 돌진해 기절시키려 할 때 (E)\'영웅의 비상\'으로 위치를 빠르게 옮겨 대응하세요. 판테온이 (E)\'방패 돌격\'을 켜고 정면 공격을 막아내는 동안에는 억지로 싸우지 말고 옆으로 돌아가서 (Q)\'복수의 부메랑\'을 맞춰야 해요.', lv6: '판테온이 (R)\'거대 유성\'을 사용하여 다른 라인에 개입하면 즉시 맵을 확인하고 라인 상황을 체크하세요. 판테온의 체력이 낮아진 순간에 (R)\'인과응보\'를 사용하여 처치 각을 보고 (E)\'영웅의 비상\'으로 빠르게 진입하세요.', item: '첫 코어로 징수의 총을 선택해 순간적인 피해량을 높이세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화를 사용해 판테온의 체력을 깎아 (R)\'인과응보\'의 킬각을 더 확실하게 잡으세요.' },
    '피들스틱': { lv1: '1~2레벨에는 (Q)\'복수의 부메랑\'으로 멀리서 피들스틱의 체력을 깎으며 미니언을 챙겨요. 상대가 부쉬에 숨어 (Q)\'공포\'를 사용하는 상황을 조심하며 거리를 유지해야 해요. 초반 마법 피해가 들어오기 전에 최대한 견제하며 라인을 관리하세요.', lv3: '3레벨에는 (E)\'영웅의 비상\'을 사용하여 피들스틱의 (E)\'수확\' 중심부에서 벗어나 침묵을 피하는 것이 좋아요. 피들스틱이 (W)\'풍작\'으로 주변 적의 체력을 흡수하려 하면 범위 밖으로 벗어나 (Q)\'복수의 부메랑\'으로 견제하세요. 상대의 (Q)\'공포\' 사거리 밖에서 스킬을 맞히며 압박하세요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'으로 갑자기 나타날 수 있으니 항상 시야를 넓게 확보해야 해요. 상대의 체력이 낮아진 것을 확인했다면 (R)\'인과응보\'를 사용하여 확실하게 처치하세요. 정글러가 근처에 있다면 상대의 궁극기가 빠진 타이밍을 노려 함께 압박하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 피들스틱의 마법 피해를 견디고 강인함을 얻어 군중 제어 지속시간을 줄이기 위해 선택해요.', spell: '점멸과 정화. 피들스틱의 (Q)\'공포\'를 빠르게 풀고 다음 행동을 이어가기 위해 사용해요.' },
    '피오라': { lv1: '(Q)\'복수의 부메랑\'으로 멀리서 피오라를 견제하며 거리를 유지하세요. 피오라가 (Q)\'찌르기\'로 급소에 접근하지 못하도록 주의하며 짧게 딜교환을 진행하세요. (P)\'치명적인 검무\'로 급소를 맞히면 회복력이 높으니 무빙에 신경 써야 해요.', lv3: '피오라가 (W)\'응수\'를 사용하면 모든 공격과 이동 불가 효과를 막아내니 (Q)\'복수의 부메랑\'을 낭비하지 마세요. 피오라의 (W)\'응수\'가 빠진 것을 확인한 뒤 (E)\'영웅의 비상\'으로 진입하여 딜교환을 시도하세요. 피오라가 (E)\'대가의 검술\'로 둔화를 걸며 다가올 때는 (E)\'영웅의 비상\'으로 빠르게 거리를 벌리세요.', lv6: '피오라가 (R)\'대결투\'를 사용하여 급소를 드러내면 (E)\'영웅의 비상\'으로 위치를 계속 바꿔 급소를 맞지 않게 조심하세요. 적의 체력이 낮을 때 (R)\'인과응보\'를 사용하여 확실하게 마무리하세요. 피오라가 (R)\'대결투\'를 통해 체력을 회복하며 버티지 못하도록 정글러와 함께 압박하세요.', item: '피오라의 기본 공격 피해를 줄이기 위해 판금 장화를 먼저 올리세요. 생명력 흡수를 챙기기 위해 첫 코어로 굶주린 히드라를 선택하세요.', spell: '점멸과 점화. 피오라가 (P)\'치명적인 검무\'로 체력을 회복할 때 점화로 그 효과를 줄이세요.' },
    '하이머딩거': { lv1: '1~2레벨에는 (Q)\'H-28 G 진화형 포탑\'이 설치된 구역에 무리하게 들어가지 마세요. (Q)\'복수의 부메랑\'을 던져 포탑을 하나씩 제거하며 하이머딩거의 진영을 무너뜨려야 해요. 포탑 주변에서는 상대의 이동 속도가 빨라지니 짧은 평타 교환만 하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중앙 기절을 피하는 것이 가장 중요해요. 수류탄이 빠진 것을 확인하고 (E)\'영웅의 비상\'으로 빠르게 진입해 (P)\'비열한 싸움\'의 보호막을 얻으며 공격하세요. (W)\'마법공학 초소형 로켓\'이 모이는 위치를 계속 움직여 피하며 딜교환을 유도하세요.', lv6: '(R)\'업그레이드!!!\'로 강화된 수류탄이나 포탑의 피해가 매우 크니 하이머딩거가 궁극기를 사용한 직후에는 주의하세요. 체력이 낮은 상대에게 (R)\'인과응보\'를 충전해 발사하세요. 포탑이 많은 곳으로 정면 돌파하기보다 (E)\'영웅의 비상\'으로 지형을 활용해 진입하는 게 좋아요.', item: '마법사의 최후를 가서 마법 저항력을 챙기고 빠른 공격 속도로 포탑을 제거하세요. 신발은 수류탄의 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 하이머딩거는 포탑 뒤에서 버티는 능력이 좋으니 점화로 체력을 깎아 확실하게 마무리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_akshan);
if (typeof module !== 'undefined') module.exports = top_akshan;
